export const ARABIC_ASSESSMENT_BANK = [[{"id":"8908fdae-bcc9-4363-bb65-072268db6471","t":"sciences","p":"What does the term al-bayān (البيان) refer to in the context of Sūrah al-Raḥmān?","o":["Eloquent speech and the ability to express internal thoughts","The ability to write complex calligraphy","The physical strength to perform manual labor","The science of calculating the movements of the sun and moon"],"e":"Al-bayān is the gift of clear and eloquent communication that allows humans to articulate their complex internal emotions and spiritual realities.","s":"Overview of the Arabic Language · Lesson 1"},{"id":"c9386f11-9bda-4073-9bb4-69dcfcde684e","t":"sentences","p":"The science of ʿIlm al-Waḍʿ (علم الوضع) is primarily concerned with which level of language?","o":["The coining or assigning of specific meanings to arrangements of letters","The rules of sentence construction","The physical articulation of letters","The historical development of regional dialects"],"e":"ʿIlm al-Waḍʿ deals with how specific words are established to represent specific meanings in a language.","s":"Overview of the Arabic Language · Lesson 1"},{"id":"43ccc210-9b04-4b61-b3ec-fbb5c0d798bc","t":"concepts","p":"What is the base meaning of the root letters N-Ṣ-R (ن-ص-ر)?","o":["To help","To write","To read","To ask"],"e":"The root N-Ṣ-R (ن-ص-ر) carries the fundamental meaning of providing assistance or helping.","s":"Overview of the Arabic Language · Lesson 2"},{"id":"716b74e0-7559-42b4-b30c-bfcb7487d485","t":"roles","p":"What ending does the fāʿil (الْفَاعِل - the doer) typically take in a standard Arabic sentence?","o":["ḍammah (ُ)","fatḥah (َ)","kasrah (ِ)","sukūn (ْ)"],"e":"A ḍammah on the final letter of a noun indicates that the noun is the doer (fāʿil) of the action.","s":"Overview of the Arabic Language · Lesson 2"},{"id":"7055bd1e-cdce-4213-abbf-c4736a857ba3","t":"concepts","p":"What does iʿrāb (إِعْرَاب) specifically deal with?","o":["The change in word endings to show grammatical roles","The derivation of root letters","The rules of tajwīd and pronunciation","The historical context of a verse"],"e":"Iʿrāb is the system where the final vowel of a word changes based on its role in the sentence structure.","s":"Overview of the Arabic Language · Lesson 2"},{"id":"a89c2601-9e0a-4f9e-a33d-7b99b528ef64","t":"sciences","p":"Which science primarily ensures that the 'gears' of the language—the individual words—are formed with the correct shape and internal structure?","o":["Ṣarf (Morphology)","Naḥw (Grammar)","Balāghah (Rhetoric)","Tafsīr (Exegesis)"],"e":"Ṣarf deals with the internal patterns and forms of words, particularly verbs, to ensure they are shaped correctly for the intended tense or meaning.","s":"Overview of the Arabic Language · Lesson 3"},{"id":"b822fd7d-13d0-4238-bf66-bd73e3d9577c","t":"roles","p":"In the Qur'ānic verse 'waritha Sulaymānu Dāwūda', why is Sulaymān recognized as the doer (heir) despite his position?","o":["Because his name ends with a ḍammah (u sound)","Because his name appears before the object","Because he was the son of Dāwūd","Because the verb always indicates the first name is the doer"],"e":"In Arabic, the grammatical function is determined by the ḥarakah (ending vowel); a ḍammah identifies the fāʿil (doer).","s":"Overview of the Arabic Language · Lesson 3"},{"id":"12362ee7-f756-40cb-920a-3c26e11c2675","t":"conjugation","p":"What is the primary difference between an Ism (اسم) and a Fiʿil (فعل)?","o":["The Fiʿil is associated with a tense, while the Ism is not.","The Ism has no meaning in itself.","The Fiʿil has no meaning in itself.","The Ism is associated with a tense, while the Fiʿil is not."],"e":"Both indicate a meaning in and of themselves, but the Fiʿil is inherently tied to a timeframe (past, present, or future), whereas the Ism is independent of time.","s":"Overview of the Arabic Language · Lesson 4"},{"id":"b4280eb3-8767-49f5-aa09-57da0fa875dc","t":"conjugation","p":"What is the definition of a Ḥarf (حرف) in Arabic grammar?","o":["A word that indicates a meaning in something else.","A word that indicates a meaning in itself without a tense.","A word that indicates a meaning in itself with a tense.","A sound that has no meaning at all."],"e":"A Ḥarf does not convey a complete meaning in isolation; it requires being joined with an Ism or Fiʿil to manifest its purpose, like the word 'in' or 'and'.","s":"Overview of the Arabic Language · Lesson 4"},{"id":"2c28362b-e22e-457f-8167-bd41bbf4d83d","t":"conjugation","p":"Which of these is a mnemonic used to recognize the beginning of an al-Muḍāriʿ (المضارع) verb?","o":["Atayna (أتين)","Yanmu (ينمو)","Sawfa (سوف)","Mufīd (مفيد)"],"e":"The letters Alif, Tā, Yā, and Nūn (summarized as Atayna) must appear at the start of every Muḍāriʿ verb.","s":"Overview of the Arabic Language · Lesson 4"},{"id":"9c6cb6b0-7f6c-452d-aa3c-878443b57721","t":"parts","p":"What are the two primary effects of adding alif-lām (ال) to an indefinite ism?","o":["It makes the word specific and removes the tanwīn.","It makes the word plural and adds a shaddah to the end.","It makes the word masculine and adds a tanwīn.","It changes the word into a verb and removes the final vowel."],"e":"Alif-lām changes the meaning from general (nakirah) to specific (maʿrifah) and phonologically forces the removal of the double vowel (tanwīn).","s":"Overview of the Arabic Language · Lesson 5"},{"id":"e7acded5-3831-438f-a13b-8e220c43b395","t":"parts","p":"What is the primary sign of a nakirah (indefinite) ism in Arabic?","o":["The doubling of the end vowel, known as tanwīn (ـٌ).","The presence of a prefix like 'min'.","Ending the word with a long tāʾ maftūḥah.","The absence of any vowels on the root letters."],"e":"Tanwīn indicates that a word is general or non-specific, acting as the Arabic equivalent of 'a' or 'an'.","s":"Overview of the Arabic Language · Lesson 5"},{"id":"a3a8ff8e-1971-4031-b456-278509b6d318","t":"concepts","p":"What is the correct sound masculine plural for the word Muslim (مُسْلِم)?","o":["Muslimūna (مُسْلِمُونَ)","Muslimāt (مُسْلِمَات)","Muslimāni (مُسْلِمَانِ)","Muslimatun (مُسْلِمَة)"],"e":"The sound masculine plural is formed by adding the suffix wāw-nūn with a fatḥah to the singular masculine base.","s":"Overview of the Arabic Language · Lesson 6"},{"id":"bac1113d-af7f-46af-a313-5ac46bcbcf17","t":"concepts","p":"In Sūrah an-Nisā’, what is the difference between 'rasūlin' (رسولٍ) and 'al-rasūlu' (الرسولُ)?","o":["The first is any messenger, while the second refers specifically to the Prophet ﷺ.","The first is plural, and the second is singular.","The first is masculine, and the second is feminine.","There is no difference in meaning between the two."],"e":"The indefinite 'rasūlin' refers to the general category of messengers, while the definite 'al-rasūlu' specifies a particular messenger.","s":"Overview of the Arabic Language · Lesson 6"},{"id":"892d2945-aeda-41d8-83e8-8f7e8c45fff7","t":"parts","p":"Why is 'al-mashḥūn' (المشحون) in Sūrah Yāsīn not considered a sound masculine plural?","o":["Because the nūn has a kasrah and the letters are part of the original root, not added suffixes.","Because it is feminine.","Because it does not end in wāw-nūn.","Because it is an indefinite noun."],"e":"In a sound masculine plural, the wāw-nūn is an added suffix and the nūn must have a fatḥah; in 'al-mashḥūn', these letters are part of the singular word's root.","s":"Overview of the Arabic Language · Lesson 6"},{"id":"4ca31869-fa95-47c0-adfa-794adbadbed5","t":"conjugation","p":"In the conjugation table, how many distinct forms are used to account for the various doers (fāʿil) of a single verb?","o":["14","6","10","12"],"e":"The standard Arabic conjugation table consists of 14 forms to cover gender, number, and person.","s":"Overview of the Arabic Language · Lesson 7"},{"id":"fbcc5d4f-13ae-4a2f-a047-8e2012543685","t":"conjugation","p":"In the past tense verb 'naṣarū' (نصروا), what is the apparent pronoun (ḍamīr bāriz) representing the doer?","o":["The Wāw","The Alif","The Nūn","The Rāʾ"],"e":"The Wāw at the end of the verb represents the masculine plural doer (they).","s":"Overview of the Arabic Language · Lesson 7"},{"id":"516f012c-36a8-4871-9de7-f874b138d9c0","t":"conjugation","p":"Which of the following conjugations contains a hidden (mustatir) pronoun?","o":["Naṣarat","Naṣarū","Naṣarna","Naṣartu"],"e":"In the māḍī table, the first conjugation (naṣara) and the fourth conjugation (naṣarat) have hidden pronouns (huwa and hiya).","s":"Overview of the Arabic Language · Lesson 8"},{"id":"742d61be-687b-45f5-9b4e-0bf5d006e6c2","t":"parts","p":"What does the 'tā’' with a sukūn (ت) in 'naṣarat' represent?","o":["A sign of femininity (tā’ al-ta’nīth)","The pronoun 'she'","The pronoun 'you'","The dual marker"],"e":"The tā’ with a sukūn is merely a marker of femininity; the pronoun 'hiya' (she) remains hidden within the verb.","s":"Overview of the Arabic Language · Lesson 8"},{"id":"e94aea8f-f8d0-41ad-8e3d-911ba1ddbb93","t":"conjugation","p":"What is the defining characteristic of a ḥarf (حرف) in Arabic grammar?","o":["It indicates a meaning only when associated with something else.","It indicates a meaning in itself attached to a tense.","It indicates a meaning in itself without a tense.","It must always start with an Alif-Lām."],"e":"Unlike the noun and verb, a particle lacks independent significance and requires a context or connection to other words to convey its full meaning.","s":"Overview of the Arabic Language · Lesson 9"},{"id":"e7726397-6fec-4b34-8337-e4570abfea22","t":"sentences","p":"Why is the definite article Alif-Lām (ال) classified as a ḥarf muhmal (حرف مهمل)?","o":["Because it does not change the grammatical position (vowel type) of the noun.","Because it changes the meaning of a noun to definite.","Because it can only be used with masculine nouns.","Because it is always inactive in every sentence."],"e":"Although Alif-Lām removes the tanwīn, it does not change the type of vowel (e.g., from ḍammah to fatḥah), meaning it does not shift the word's grammatical position.","s":"Overview of the Arabic Language · Lesson 9"},{"id":"b2a465b3-4ff7-4a47-9be0-bc6bdad4e300","t":"conjugation","p":"What is the primary purpose of Iʿrāb (إعراب) in the Arabic language?","o":["To identify the functional role of a word through its ending.","To help students memorize conjugation tables.","To distinguish between definite and indefinite nouns.","To determine if a word is a noun, verb, or particle."],"e":"Iʿrāb is the system of inflection where changes in word endings reveal the word's grammatical role and position in a sentence.","s":"Overview of the Arabic Language · Lesson 9"},{"id":"9e050be7-8a0c-4b36-9131-0ffc71f789fc","t":"concepts","p":"What is the meaning of the preposition 'ilā' (إلى)?","o":["To","In","From","On"],"e":"The preposition 'ilā' indicates a destination or end point, translated as 'to'.","s":"Overview of the Arabic Language · Lesson 10"},{"id":"d302a3c0-caae-4d34-9134-d8024a64cf13","t":"parts","p":"In the phrase 'fī al-bayti' (في البيتِ), what is the 'Role' of the word 'al-bayti'?","o":["Majrūr","Jarr","Kasrah","Ism"],"e":"The 'Role' is the specific grammatical function (Majrūr), while 'Jarr' is the position and 'Kasrah' is the reflection.","s":"Overview of the Arabic Language · Lesson 10"},{"id":"ac7707a3-e07f-40c8-84d1-76c92af37ef3","t":"roles","p":"What is the technical term for the 'possessed' object in an Arabic possessive phrase?","o":["Mudhāf","Mudhāf ilayh","Majrūr","Murakkab"],"e":"In the possessive construction, the mudhāf is the object or entity that is being owned or attributed to another.","s":"Overview of the Arabic Language · Lesson 11"},{"id":"502d3baf-bb64-4ae8-8bfd-115ff9fc873e","t":"concepts","p":"Which English structure follows the same word order as the Arabic possessive phrase?","o":["The 'of' method (e.g., The book of Zayd)","The apostrophe 's' method (e.g., Zayd's book)","The 'the' prefix method (e.g., The book Zayd)","The adjective method (e.g., The Zaydean book)"],"e":"Arabic requires the possessed object to come before the possessor, which matches the order of the English 'of' structure but is the opposite of the apostrophe 's' structure.","s":"Overview of the Arabic Language · Lesson 11"},{"id":"e938e139-5e6d-49f3-9bee-3bbdb5c1b680","t":"concepts","p":"In the phrase 'ʿalā maktabi al-mudarrisi', what is the grammatical function of the word 'maktabi'?","o":["Both majrūr and muḍāf","Only majrūr","Only muḍāf","Both muḍāf and muḍāf ilayh"],"e":"It is majrūr because it follows the preposition 'ʿalā' and muḍāf because it is the 'possessed' item relative to the teacher.","s":"Overview of the Arabic Language · Lesson 12"},{"id":"a391fc1a-d5c9-439b-9c25-bb94816f29e8","t":"roles","p":"What is the definition of the term mawṣūf (مَوْصُوف) in Arabic grammar?","o":["The entity being described","The description or adjective","The doer of an action","The possessor in a phrase"],"e":"Mawṣūf literally means 'the one being described' and serves as the anchor for the descriptive phrase.","s":"Overview of the Arabic Language · Lesson 13"},{"id":"f8b57dd1-7e15-41bb-a33f-0c142234477c","t":"concepts","p":"How many total 'traits' result from the four aspects of correspondence that a ṣifah must match in its mawṣūf?","o":["Ten","Four","Seven","Twelve"],"e":"The four aspects (definiteness, gender, number, and case) expand into ten possible traits: 2 for definiteness, 2 for gender, 3 for number, and 3 for case.","s":"Overview of the Arabic Language · Lesson 13"},{"id":"50e3c608-536d-4a89-ab34-231b7bd31b21","t":"parts","p":"What is the primary rule regarding the order of the descriptive phrase (al-mawṣūf wa al-ṣifah) in Arabic?","o":["The noun being described (mawṣūf) must always come first.","The description (ṣifah) must always come first.","The order depends on whether the phrase is definite or indefinite.","The order is interchangeable depending on emphasis."],"e":"In Arabic syntax, the mawṣūf (the one being described) must precede the ṣifah (the description).","s":"Overview of the Arabic Language · Lesson 14"},{"id":"a3f50d66-3de1-4033-9bbe-47dd72d2dcb0","t":"concepts","p":"In how many specific categories must the ṣifah match the mawṣūf?","o":["Four","Two","Three","Five"],"e":"The ṣifah must match the mawṣūf in four areas: definiteness/indefiniteness, gender, amount (number), and grammatical position (iʿrāb).","s":"Overview of the Arabic Language · Lesson 14"},{"id":"e608754f-58c5-4662-bbe3-081e194d612e","t":"parts","p":"What is the term for a compound structure that provides a complete meaning upon which silence is appropriate?","o":["Murakkab mufīd","Mufrad","Murakkab ghayr mufīd","Ḥarf"],"e":"A murakkab mufīd is a beneficial compound, also known as a sentence, which provides a full meaning so that the listener is not left waiting for more information.","s":"Overview of the Arabic Language · Lesson 15"},{"id":"55d1c0da-689c-4e4e-a592-3806a54b3afb","t":"roles","p":"In a nominal sentence (jumlah ismiyyah), what is the technical name for the subject (musnad ilayh)?","o":["Mubtadaʾ","Fiʿl","Fāʿil","Khabar"],"e":"The subject of a nominal sentence is called the mubtadaʾ, which literally means that which is begun with.","s":"Overview of the Arabic Language · Lesson 15"},{"id":"8cdd3c32-d313-4abe-af89-f118e45b0d83","t":"sentences","p":"What is the standard grammatical state (iʿrāb) for both the mubtadaʾ and the khabar?","o":["Rafaʿ (Nominative)","Jarr (Genitive)","Naṣab (Accusative)","Jazm (Jussive)"],"e":"Both the subject (mubtadaʾ) and the predicate (khabar) occupy the position of rafaʿ, typically indicated by a ḍammah or ḍammatayn.","s":"Overview of the Arabic Language · Lesson 16"},{"id":"283bf73f-87ca-4d51-8c90-c1af90064256","t":"sentences","p":"In the sentence 'al-ʿuṣfūru sarīʿun' (the sparrow is fast), why is the word 'sarīʿun' indefinite?","o":["Because it is the khabar, and the khabar is generally indefinite (nakirah)","Because it is an adjective describing the sparrow in a phrase","Because it is the muḍāf ilayh in a possessive construction","Because it is the mubtadaʾ of the sentence"],"e":"A mismatch in definiteness—where the mubtadaʾ is definite and the khabar is indefinite—is the primary indicator of a complete nominal sentence.","s":"Overview of the Arabic Language · Lesson 16"},{"id":"1b757c08-11a1-414a-8043-a0e8053a372d","t":"parts","p":"Which of the following describes the behavior of hamzat al-waṣl (همزة الوصل) in the phrase 'wa-bnu Yāsirin' (وابن ياسر)?","o":["It becomes silent and is not pronounced.","It is pronounced with a fatḥah.","It is pronounced with a kasrah.","It is written with a hamza symbol on top."],"e":"Hamzat al-waṣl is only pronounced when starting a sentence; when preceded by another word like the waw (و), it is skipped in pronunciation.","s":"Overview of the Arabic Language · Lesson 17"},{"id":"5131ad3b-a494-456d-afbf-ed5bf5e15dc0","t":"sentences","p":"In the sentence 'al-ʿArabiyyatu lughatun sahlatun' (العربية لغة سهلة), what is the relationship between 'lughatun' and 'sahlatun'?","o":["Mawṣūf and ṣifah","Muḍāf and muḍāf ilayh","Mubtadaʾ and khabar","Ḥarf al-jarr and majrūr"],"e":"These two words form an adjectival phrase where 'lughatun' (language) is being described by 'sahlatun' (easy).","s":"Overview of the Arabic Language · Lesson 17"},{"id":"e96318ec-f575-449d-8167-48e2d8a623c7","t":"sentences","p":"In the sentence 'al-lughatu al-ʿArabiyyatu sahlatun' (اللغة العربية سهلة), what is the khabar?","o":["sahlatun","al-lughatu","al-ʿArabiyyatu","al-lughatu al-ʿArabiyyatu"],"e":"In this structure, 'al-lughatu al-ʿArabiyyatu' forms the subject unit (The Arabic language), and 'sahlatun' provides the information that it is easy.","s":"Overview of the Arabic Language · Lesson 17"},{"id":"07534fe4-cc59-463c-a8b8-a13e80215e55","t":"roles","p":"What is the primary defining characteristic of a verbal sentence (al-jumlat al-fiʿliyyah)?","o":["It begins with a verb (fiʿil)","It must contain a hidden pronoun","It starts with a noun (ism)","The doer must precede the verb"],"e":"A verbal sentence is defined by starting with a verb, whereas a nominal sentence starts with a noun.","s":"Overview of the Arabic Language · Lesson 18"},{"id":"70f4958c-f52a-455f-98f6-3f83c7dea84a","t":"roles","p":"In the sentence 'Zaydun jalasa' (زَيْدٌ جَلَسَ), what is the fāʿil?","o":["A hidden pronoun (ḍamīr mustatir) 'huwa'","Zaydun","The verb jalasa itself","There is no fāʿil in this sentence"],"e":"Because Zaydun precedes the verb, he is the mubtadaʾ, and the verb jalasa contains a hidden pronoun 'huwa' that acts as the fāʿil.","s":"Overview of the Arabic Language · Lesson 18"},{"id":"63d3936b-0304-4212-a5b3-42922f3a6def","t":"roles","p":"Which grammatical state is required for the mafʿūl bihi (object) in an Arabic sentence?","o":["Naṣb (accusative)","Rafʿ (nominative)","Jar (genitive)","Jazm (jussive)"],"e":"The object of a verb, the mafʿūl bihi, is always in the state of naṣb, which is typically marked by a fatḥah.","s":"Overview of the Arabic Language · Lesson 19"},{"id":"82521dcf-288e-4a52-8c3b-1c239d0e3b50","t":"parts","p":"What is the purpose of the particle 'hal' (هل)?","o":["To form a question","To negate a verb","To indicate a future action","To connect two nouns"],"e":"The particle 'hal' is used to form questions, typically appearing before verbs.","s":"Overview of the Arabic Language · Lesson 19"},{"id":"caf7cb44-7bac-4727-be33-0940f9b555af","t":"sentences","p":"What is the grammatical term for a word whose ending remains fixed regardless of its position in a sentence?","o":["Mabnī","Muʿrab","Majrūr","Mubtadaʾ"],"e":"Mabnī refers to words that are 'built' or fixed in their form, meaning they do not change their vowels to reflect grammatical states like rafʿ, naṣb, or jarr.","s":"Overview of the Arabic Language · Lesson 21"},{"id":"f5ef80b1-5d5b-49d4-a9d6-df4fc1d979c4","t":"roles","p":"In the verb 'fasadatā' فَسَدَتَا (they both fell into disorder), what serves as the fāʿil (doer)?","o":["The alif at the end of the verb","The hidden pronoun 'huwa'","The letter 'tā'","The preceding noun"],"e":"In the dual feminine form of the past tense verb, the alif appended to the suffix is the attached pronoun that functions as the doer.","s":"Overview of the Arabic Language · Lesson 21"},{"id":"2ef34e67-71e3-493b-b9f0-188f265fc4ab","t":"conjugation","p":"To which person and gender does the conjugation tanṣurīna (تنصرين) refer?","o":["Second-person feminine singular","Third-person feminine singular","First-person plural","Second-person masculine plural"],"e":"The suffix yā and nūn (yā al-mukhāṭabah) specifically identifies the singular female being addressed (you).","s":"Overview of the Arabic Language · Lesson 22"},{"id":"c49252a6-9edd-4012-8131-7d184a601de0","t":"parts","p":"Identify the fā kalimah (first root letter) in the verb fataḥa (فتح).","o":["Fā","Tā","Ḥā","Alif"],"e":"In the pattern faʿala, the first letter corresponds to the fā position; for the root F-T-Ḥ, the Fā is the fā kalimah.","s":"Overview of the Arabic Language · Lesson 22"},{"id":"9ddbde77-01a1-4171-810a-044afda23af5","t":"parts","p":"Which hidden pronoun (ḍamīr mustatir) is assumed for the verb anṣuru (أنصر)?","o":["Ana","Huwa","Naḥnu","Anta"],"e":"The Hamza prefix indicates the first-person singular, meaning the hidden doer is 'I' (ana).","s":"Overview of the Arabic Language · Lesson 22"},{"id":"648cf6b0-f2c0-447a-8f94-ff1029021f94","t":"roles","p":"What is the Faail (Doer) of يَنْصُرُوْنَ?","o":["The wāw before the nūn","The yāʾ at the beginning","The nūn at the end","A hidden pronoun (huwa)"],"e":"In the masculine plural forms of the fiʿl muḍāriʿ, the wāw is the attached pronoun acting as the subject, while the nūn is merely an inflectional marker.","s":"Overview of the Arabic Language · Lesson 23"},{"id":"dd042a7c-d917-4ad2-818d-2208028acf35","t":"roles","p":"If the verb tanṣuru (تَنْصُرُ) is used for the second person masculine singular (مفرد مذكر مخاطب), what is its doer?","o":["A hidden anta (أَنْتَ)","The tāʾ at the beginning","A hidden hiya (هِيَ)","A visible nūn"],"e":"In the singular second-person masculine form, the doer is an implied or hidden pronoun (anta) because the ending of the verb is empty of an attached pronoun.","s":"Overview of the Arabic Language · Lesson 23"},{"id":"1ced25f4-7d2c-4937-b626-746c7d46dd69","t":"roles","p":"What is the doer of the verb nanṣuru (نَنْصُرُ) if no visible noun follows it?","o":["A hidden naḥnu (نَحْنُ)","The nūn at the beginning","An attached alif","A hidden ana (أَنَا)"],"e":"The 1st person plural conjugation is one of the five 'empty' forms that takes a hidden pronoun (we) as its subject.","s":"Overview of the Arabic Language · Lesson 23"},{"id":"c3182b97-2231-436f-8568-7326c408ed8c","t":"sentences","p":"What is the primary purpose of studying al-Iʿrāb (grammatical inflection) in Arabic grammar?","o":["To identify the grammatical role a word plays in a sentence","To memorize a specific list of vocabulary words","To distinguish between poetry and prose","To learn the historical development of the Arabic script"],"e":"Al-Iʿrāb is the system that defines the role a word plays—such as subject, object, or possessor—and how that role is reflected through specific word endings.","s":"Overview of the Arabic Language · Lesson 24"},{"id":"cc21e4b4-059b-4547-b676-c3dfa168c93a","t":"roles","p":"In the sentence 'Jāʾa Ḥāmidun' (جاء َ حامدٌ), what is the grammatical role of 'Ḥāmidun'?","o":["The subject/doer (fāʿil)","The predicate (khabar)","The direct object (mafʿūl bihī)","The possessor (muḍāf ilayh)"],"e":"In a verbal sentence, the apparent noun appearing after the verb that performs the action is the fāʿil (subject).","s":"Overview of the Arabic Language · Lesson 24"},{"id":"717e31a2-7fa4-4e3e-a6dc-3fd42f87fa8f","t":"parts","p":"How many total grammatical roles exist across all four positions for both nouns and verbs?","o":["25","13","22","30"],"e":"There are 25 total roles: 22 belonging to the ism and 3 belonging to the fiʿl muḍāriʿ.","s":"Overview of the Arabic Language · Lesson 25"},{"id":"d569396a-5ab4-4d6b-8410-8901cfa106ed","t":"concepts","p":"In the phrase 'Innallāha ghafūrun' (إن اللهَ غفورٌ), what is the grammatical position of 'ghafūrun' (غفورٌ)?","o":["Rafʿ","Naṣb","Jarr","Jazm"],"e":"Ghafūrun is the khabar of inna, which remains in the position of rafʿ.","s":"Overview of the Arabic Language · Lesson 25"},{"id":"ac6b8b2d-202e-409e-865a-0d195499f547","t":"concepts","p":"How many grammatical roles are exclusive to the position of al-jarr (الجر)?","o":["Two roles","One role","Eight roles","Twelve roles"],"e":"There are only two ways for a word to enter the position of jarr: being preceded by a preposition or acting as a muḍāf ilayh.","s":"Overview of the Arabic Language · Lesson 26"},{"id":"e9d5ae03-0f38-46c8-bbdc-a2cf1c91f964","t":"sentences","p":"When the particle 'inna' (إِنَّ) enters a nominal sentence, what is the resulting I'rāb of the subject (ism)?","o":["Naṣb","Rafʿ","Jarr","Jazm"],"e":"The particle inna puts its ism into the position of naṣb while the khabar remains in the position of rafʿ.","s":"Overview of the Arabic Language · Lesson 26"},{"id":"776205b4-cf5d-42d5-8f54-c255b1a9a9e4","t":"roles","p":"In the Qurʾānic verse 'Fasajadū illā Iblīsa' (فسجدوا إلّا إبليسَ), what is the grammatical role of 'Iblīsa' (إبليس)?","o":["Al-Mustathnā","Al-Ḥāl","Al-Tamyīz","Nāʾib al-Fāʿil"],"e":"Iblīs is the mustathnā because he is excluded from the general ruling of prostration using the particle illā.","s":"Overview of the Arabic Language · Lesson 26"},{"id":"3e665886-4e43-4a03-9feb-5a7bb07cf18d","t":"sentences","p":"When the particle Inna (إِنَّ) enters a nominal sentence, what happens to the Mubtadaʾ?","o":["It becomes the Ism of Inna and shifts to the position of naṣb","It remains in the position of rafʿ as the Khabar of Inna","It becomes the Ism of Inna and remains in the position of rafʿ","It shifts to the position of jarr because of the particle"],"e":"Inna acts as a shifter that specifically moves the subject (mubtadaʾ) into the state of naṣb.","s":"Overview of the Arabic Language · Lesson 27"},{"id":"3d712cbd-4cb2-4a96-914f-08f6815b90a1","t":"conjugation","p":"In the word 'sa'alnāhu' (سَأَلْنَاهُ), what role does the suffix '-hu' play?","o":["The object of the action (mafʿūl bihi)","The past tense verb root","The doer of the action (fāʿil)","The sign of the present tense"],"e":"The suffix '-hu' is a attached pronoun representing the object 'him', answering the question 'whom did we ask'.","s":"Overview of the Arabic Language · Lesson 27"},{"id":"1888cd43-784d-42df-8276-2221c9463e43","t":"parts","p":"In the phrase 'ilā Madīnati al-Nabiyyi' (إلى مدينةِ النبيِّ), why is 'Madīnati' (مدينةِ) in the state of jarr?","o":["Because it follows a ḥarf al-jarr","Because it is a Muḍāf ilayh","Because it is a Ṣifah","Because it is the Ism of Inna"],"e":"The word follows the particle 'ilā', which is a ḥarf al-jarr, placing the subsequent noun in the state of jarr.","s":"Overview of the Arabic Language · Lesson 27"}],[{"id":"1b9068a7-8246-4ad4-9cfc-2a3509efd78c","t":"vocabulary","p":"What is the primary function of the Ḍamīr al-Faṣl (ضمير الفصل) in a sentence?","o":["To clarify that the following definite word is the predicate and not an adjective","To negate the meaning of the verb","To connect a muḍāf to a muḍāf ilayh","To indicate that the subject is dual"],"e":"The Pronoun of Separation is inserted between two definite words to ensure the second is understood as the khabar rather than a descriptive ṣifah.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 15"},{"id":"1abb9382-48b3-4ae6-85de-3a0012cbfb1d","t":"vocabulary","p":"What is the grammatical function of the word baʿda (بَعْدَ) in the phrase baʿda muddatin (بَعْدَ مُدَّةٍ)?","o":["Mafʿūl fīhi (Adverb of time)","Fāʿil (Doer)","Mafʿūl bihi (Object)","Ṣifah (Description)"],"e":"Words indicating the 'when' or 'where' of an action, such as 'after' (baʿda), function as a mafʿūl fīhi.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 16"},{"id":"f1b74ad4-3edc-413e-bf62-ace623e23baf","t":"reading","p":"When the verb kāna (كَانَ) enters a sentence, what is the grammatical case of its predicate (khabar)?","o":["Accusative (manṣūb)","Nominative (marfūʿ)","Genitive (majrūr)","Jussive (majzūm)"],"e":"Deficient verbs like kāna make their subject marfūʿ and their predicate (khabar) manṣūb.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 16"},{"id":"1f5dbf9a-7746-4df2-a5fa-d5ca4a7bec44","t":"reading","p":"In the phrase Bāʾiʿ al-Aṣnām (بائع الأصنام), what is the grammatical role of al-Aṣnām?","o":["Muḍāf Ilayh","Muḍāf","Ṣifah","Ism Kāna"],"e":"Bāʾiʿ is the muḍāf (seller), and al-Aṣnām is the muḍāf ilayh (the idols), which is in the state of jarr.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 1"},{"id":"26b7f794-0dbd-4398-b192-34e7d72f0c14","t":"vocabulary","p":"What does the term Fiʿl Nāqiṣ (فعل ناقص) literally mean in the context of the verb kāna?","o":["Deficient verb","Perfect verb","Transitive verb","Future verb"],"e":"Kāna is called a deficient verb because it does not take a standard doer (fāʿil) but requires a subject and a predicate to complete its meaning.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 1"},{"id":"00c86f80-cda5-48a3-8f96-d5b15bce35e0","t":"reading","p":"Which category of reflection do pronouns and demonstratives like 'hādhā' fall into?","o":["Non-reflecting (mabnī)","Standard reflection","Alternative reflection","Diptote reflection"],"e":"Mabnī words occupy grammatical positions but do not change their physical endings or vowels.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 2"},{"id":"1478f391-ccd5-45a0-8729-5781094f0f56","t":"reading","p":"In the construction 'Nasīḥatu Ibrahīma', why does the name Ibrahim end with a single fatha?","o":["Because foreign names are diptotes and use a fatha to reflect the state of jarr","Because it is the object of the advice","Because it is the subject of a nominal sentence","Because it is followed by a hidden pronoun"],"e":"Foreign names like Ibrahīm are diptotes (ghayr munṣarif), which do not accept tanwīn or kasra, reflecting the state of jarr with a single fatha.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 3"},{"id":"186af810-b683-4123-bad1-fa02fd172ca6","t":"reading","p":"In the sentence 'Ibrāhīm yaksiru al-aṣnāma' (إبراهيم يكسر الأصنام), what is the grammatical role of 'Ibrāhīm'?","o":["Mubtadaʾ (Subject)","Fāʿil (Doer)","Mafʿūl bihī (Object)","Mawṣūf (Noun being described)"],"e":"Since the sentence begins with a noun, it is a nominal sentence (jumlah ismiyyah), and Ibrāhīm is the mubtadaʾ; he cannot be the fāʿil because a doer cannot precede its verb.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 4"},{"id":"e6be786e-e595-401b-9a5b-67c9cabe03dc","t":"vocabulary","p":"What grammatical structure is formed by 'hādhā taʿāmun' (هذا طعام) without the 'alif-lām'?","o":["A complete nominal sentence meaning 'this is food'.","An incomplete phrase meaning 'this food'.","A possessive construction (iḍāfah).","A verbal sentence."],"e":"When a demonstrative pronoun is followed by a noun without alif-lām, it forms a complete sentence (mubtadaʾ and khabar).","s":"Qaṣaṣ al-Nabiyyīn · Lesson 4"},{"id":"0432e478-28fa-4590-b532-7e16f8f325d2","t":"reading","p":"Which particle is considered a nāṣib that causes the fiʿl muḍāriʿ to enter the state of nasab?","o":["An (أن)","Inna (إنّ)","Anna (أنّ)","Lā (لا)"],"e":"The particle an (أن) is an operative particle (muʿmal) that specifically enters upon verbs and causes them to enter the state of nasab.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 5"},{"id":"c1ae7c0b-1796-4e22-a31f-9bc9ccbd5596","t":"reading","p":"What grammatical effect does the particle anna (أَنَّ) have on a nominal sentence?","o":["It places the ism into the state of naṣb while the khabar remains in rafʿ.","It causes both the subject and predicate to enter the state of jarr.","It causes the subject to remain in rafʿ and the predicate to enter naṣb.","It has no grammatical influence on the nouns following it."],"e":"Anna is a 'sister' of inna (ḥarfun mushabbahun bi’l-fiʿl), which places its noun (ism) in the accusative (naṣb) and keeps its predicate (khabar) in the nominative (rafʿ).","s":"Qaṣaṣ al-Nabiyyīn · Lesson 5"},{"id":"f8ecba7d-b1bc-48e5-9055-69ad0ddd7d77","t":"vocabulary","p":"What is the primary reason the word bāridatun (بَارِدَة) is feminine in the phrase nārun bāridatun?","o":["The word nār (نَار) is Muʾannath Samaʿī (feminine by usage)","Fire has an intrinsically feminine biological nature","The word nār (نَار) ends in a hidden tāʾ marbūṭah","Adjectives in Arabic are always feminine by default"],"e":"Nār is classified as Muʾannath Samaʿī, meaning it is treated as feminine by the Arabs despite lacking physical feminine attributes or a feminine suffix.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 6"},{"id":"7290ded2-3240-43b4-ad0a-9bd862f70bbe","t":"vocabulary","p":"What is the plural of the word nār (نَار)?","o":["Nīrān (نِيرَان)","Nārāt (نَارَات)","Anwār (أَنْوَار)","Nūr (نُور)"],"e":"The broken plural for the word nār (fire) is nīrān.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 6"},{"id":"e49cfa94-4a46-44de-80fc-79900b21fefc","t":"vocabulary","p":"What is the plural of the word kawkab (كوكب)?","o":["Kawākib","Akwaakib","Akmār","Kawkabāt"],"e":"The broken plural of kawkab (star) is kawākib (stars).","s":"Qaṣaṣ al-Nabiyyīn · Lesson 7"},{"id":"56e3e90c-0fd6-4751-b25c-979b9b2b98db","t":"vocabulary","p":"What is the grammatical relationship between the components of the word Rabbī (رَبِّي)?","o":["Muḍāf and Muḍāf ilayh","Mubtada' and Khabar","Fiʿl and Fāʿil","Mawṣūf and Ṣifah"],"e":"Rabbī is a combination of the noun Rabb and the attached pronoun yā', which always creates a possessive construction.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 8"},{"id":"bdd772a9-3e0c-49cc-bea2-615b566b1168","t":"reading","p":"What grammatical role does the interrogative noun 'mā' (مَا) play in the sentence 'Mā taʿbudūn?'","o":["The object (Mafʿūl bihi)","The subject (Fāʿil)","The predicate (Khabar)","The prepositional attachment (Mutaʿalliq)"],"e":"Interrogative nouns like 'mā' are 'mabnī' but they still fulfill specific grammatical roles in the sentence; in this case, it is the object being worshipped.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 9"},{"id":"86f0040a-bb4c-49c7-ba5e-0695b511cd9f","t":"vocabulary","p":"What is the grammatical function of words indicating direction such as amāma (in front of) or khalfa (behind)?","o":["They function as muḍāf, requiring the following noun to be in jarr.","They function as fāʿil, requiring the following noun to be in rafʿ.","They function as ṣifah, matching the case of the preceding noun.","They function as ḥarf al-jarr, being fixed in their endings."],"e":"Directional and temporal words like amāma function as the first term in a possessive construction (muḍāf), causing the subsequent noun (muḍāf ilayh) to take the genitive case.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 10"},{"id":"729a6efc-1abb-4c96-a020-f61ca5488393","t":"reading","p":"What is the primary function shared by both anna (أنَّ) and an (أنْ)?","o":["Converting a sentence into a non-sentence or phrase","Giving rafʿ to the subject","Acting as a preposition for nouns","Linking a subject to a hidden predicate"],"e":"Both particles possess the special power to de-sentence a structure, allowing it to fulfill roles that a full sentence cannot.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 10"},{"id":"aee2dcb3-36da-44cc-a97e-b1841745d775","t":"vocabulary","p":"What is the primary grammatical function of the particle 'an' (أَنْ) when it precedes a fiʿl muḍāriʿ?","o":["It converts the verbal sentence into a verbal noun (maṣdar) meaning","It changes the verb to the past tense","It makes the verb indefinite","It acts as a particle of negation"],"e":"Known as an al-maṣdariyyah, it transforms the verbal sentence into a unit that can function as a single noun, such as a direct object.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 11"},{"id":"fdaa252d-cbd4-49eb-bb55-c6dd8f7b137e","t":"vocabulary","p":"What is the grammatical reason 'Ibrāhīma' cannot be the direct object of 'ghaḍiba' (became angry) in 'ghaḍiba qawmu Ibrāhīma'?","o":["The verb ghaḍiba is lāzim (intransitive) and cannot take a direct object","Ibrāhīma is in the state of rafʿ","The word qawmu must always be a muḍāf","Ibrāhīma is the subject of the sentence"],"e":"The verb ghaḍiba is intransitive in Arabic, meaning it does not act directly upon an object; any person one is angry with must be introduced via a preposition.","s":"Qaṣaṣ al-Nabiyyīn · Lesson 12"},{"id":"45a20dda-da86-4456-887b-2ede5a3a60fa","t":"signs","p":"What is the primary structural difference between the usage of inna (إنّ) and anna (أنّ)?","o":["Inna occurs at the beginning of a sentence, while anna occurs in the middle.","Inna provides emphasis while anna provides doubt.","Anna makes the predicate manṣūb while inna makes it marfūʿ.","Inna is used for questions and anna is used for statements."],"e":"Both particles provide taʾkīd (emphasis), but inna is used at the start of a sentence, whereas anna integrates a nominal sentence into the middle of a larger structure.","s":"al-Shadharah al-Dhahabiyyah · Lesson 13"},{"id":"da529371-e371-47ed-9468-d0c9e404c7eb","t":"tarkib","p":"Why is the name Ibrāhīmu (إبراهيم) restricted from ṣarf?","o":["It is a proper noun (ʿalamiyyah) of foreign origin (ʿujmah).","It is a feminine name on the pattern of a verb.","It ends with an extra alif and nūn.","It follows the ultimate plural pattern."],"e":"Ibrāhīm is a proper noun of non-Arabic origin, thus combining the two causes of ʿalamiyyah and ʿujmah.","s":"al-Shadharah al-Dhahabiyyah · Lesson 14"},{"id":"7924aec4-3eb7-43be-ab54-5a04cf81afe3","t":"tarkib","p":"What causes the adjective Akbar (أكبر) to be ghayr munṣarif?","o":["It is an adjective (waṣf) on the pattern of a verb (wazn al-fiʿl).","It is a proper noun on a verb pattern.","It is an adjective of foreign origin.","It is a plural noun."],"e":"Akbar is an adjective (waṣf) and follows the morphological pattern of a verb (wazn al-fiʿl), fulfilling the requirement for two causes.","s":"al-Shadharah al-Dhahabiyyah · Lesson 14"},{"id":"34abc032-cf39-47c8-be96-d99906009688","t":"tarkib","p":"What meaning does the prefix Sīn (سـ) add to a present-tense verb?","o":["Near future ('soon')","Emphasis","Past action","Negation"],"e":"The Sīn prefix (e.g., Sayaslā) restricts the verb's meaning to the near future.","s":"al-Shadharah al-Dhahabiyyah · Lesson 1"},{"id":"dec9fb1e-ce92-4285-9044-17f210b10c40","t":"tarkib","p":"If a pronoun is attached to the particle Inna (إِنَّ), what grammatical position does it occupy?","o":["Naṣb","Rafʿ","Jarr","Jazm"],"e":"The noun or pronoun following Inna acts as its ism, which is always in the state of naṣb.","s":"al-Shadharah al-Dhahabiyyah · Lesson 2"},{"id":"681353d8-7f4e-49ff-822d-72931fe99cb3","t":"signs","p":"Which of the following is considered a definitive sign of the fiʿl māḍī (past tense verb)?","o":["Tāʾ al-fāʿil (e.g., faʿalta)","The presence of alif-lām","The ability to take tanwīn","A kasrah on the final letter"],"e":"Tāʾ al-fāʿil, the tāʾ of the doer, is a specific marker that identifies a word as a verb, particularly in the past tense.","s":"al-Shadharah al-Dhahabiyyah · Lesson 3"},{"id":"2a6abca9-e326-4632-84d5-e1bdbb6fb0e7","t":"tarkib","p":"The particle 'min' (من) is categorized as which type of particle?","o":["Mukhtaṣṣ bil-ism (Specific to nouns)","Mukhtaṣṣ bil-fiʿl (Specific to verbs)","Mushtarak (Common to both)","Muhmal (Non-governing)"],"e":"Min is a preposition that can only precede nouns and cannot enter upon verbs.","s":"al-Shadharah al-Dhahabiyyah · Lesson 4"},{"id":"cf3eb863-698f-4faf-8322-3d1fcafd4ad8","t":"tarkib","p":"What change does the particle 'lam' (لم) induce in a present tense verb?","o":["It causes the verb to enter the state of jazm","It causes the verb to enter the state of jarr","It causes the verb to enter the state of rafʿ","It causes the verb to become a noun"],"e":"Lam is a governing particle specific to verbs that induces the state of jazm, often marked by a sukūn.","s":"al-Shadharah al-Dhahabiyyah · Lesson 4"},{"id":"d9e4c7fc-0278-4ec8-9741-5e32487fac33","t":"signs","p":"What is the primary reason why the ism (noun) requires al-iʿrāb?","o":["Because it can play multiple roles in a sentence","Because it is the longest part of speech","Because it is the only part of speech that carries a tanwīn","Because it is derived from a three-letter root"],"e":"Since a single noun can function as a subject, object, or possessor, a system of terminal changes is needed to distinguish these various roles.","s":"al-Shadharah al-Dhahabiyyah · Lesson 5"},{"id":"6a7d66fd-b03a-4a4d-b6ac-6e5f1774fc9b","t":"signs","p":"Which vowel does the sound feminine plural (jamʿ al-muʾannath al-sālim) use to reflect the position of naṣb?","o":["Kasrah","Fatḥah","Ḁammah","Sukūn"],"e":"The sound feminine plural is an example of alternative reflection, where it uses a kasrah to reflect the position of naṣb instead of the standard fatḥah.","s":"al-Shadharah al-Dhahabiyyah · Lesson 6"},{"id":"aa85bc67-5d4a-4f9d-8326-7336d6d0d9f0","t":"signs","p":"What is the primary condition for the Six Nouns (al-Asmāʾ al-Sittah) to reflect their iʿrāb through letters rather than vowels?","o":["They must be annexed (muḍāf)","They must be indefinite (nakirah)","They must follow a preposition","They must be in the plural form"],"e":"The Six Nouns only use letters (wāw, alif, yāʾ) to show their grammatical state when they are muḍāf; otherwise, they revert to standard vowel-based reflection.","s":"al-Shadharah al-Dhahabiyyah · Lesson 7"},{"id":"c5039596-1229-47c2-8e00-d0b8015368fa","t":"signs","p":"Why does the fiʿl muḍāriʿ (فعل مضارع) reflect grammatical positions (iʿrāb) unlike the past tense and imperative?","o":["It resembles the noun (ism) in its ability to occupy varying grammatical roles","It carries the root meaning of the verb","It is derived from the particle (ḥarf)","It is the only verb form that takes a subject"],"e":"The fiʿl muḍāriʿ resembles the noun because it cycles through different grammatical positions within a sentence, requiring its endings to reflect those roles.","s":"al-Shadharah al-Dhahabiyyah · Lesson 8"},{"id":"a7f89ccd-c65c-42b0-a734-46e0efb9cf87","t":"tarkib","p":"When the jussive agent 'lam' is applied to 'yadʿū' (يدعو), the resulting form is:","o":["Lam yadʿu","Lam yadʿū","Lam yadʿuwa","Lam yadʿūna"],"e":"The final wāw is dropped to reflect the state of jazm.","s":"al-Shadharah al-Dhahabiyyah · Lesson 8"},{"id":"9772a4c1-00ff-4524-8bec-a929f2d09ccd","t":"tarkib","p":"What is the literal meaning of the term mabni (مبني)?","o":["Built","Changing","Weak","Grammatical"],"e":"The term mabni signifies that a word is 'built' upon a specific phonetic form that does not change regardless of its grammatical environment.","s":"al-Shadharah al-Dhahabiyyah · Lesson 9"},{"id":"acaa38b7-2532-4d87-98ef-dc8e62f4d5a2","t":"tarkib","p":"In the phrase 'rabbukum' (ربكم), what is the grammatical position of the pronoun -kum?","o":["Jarr","Rafʿ","Naṣb","It has no position"],"e":"Attached pronouns joined to an ism function as muḍāf ilayh, which is always in the position of jarr.","s":"al-Shadharah al-Dhahabiyyah · Lesson 9"},{"id":"a31ce464-c14f-4f3a-9718-c69cc6135fc4","t":"tarkib","p":"In the phrase 'Ash-shamsu taṭluʿu' (الشمس تطلع), what is the fāʿil?","o":["A hidden pronoun (ḍamīr mustatir) within 'taṭluʿu'","Ash-shamsu","The letter 'tā' at the beginning of the verb","There is no fāʿil in this sentence"],"e":"Since 'Ash-shams' precedes the verb, it cannot be the fāʿil; the doer is the hidden pronoun 'hiya' referring back to it.","s":"al-Shadharah al-Dhahabiyyah · Lesson 10"},{"id":"60522764-2836-4212-9491-03277eb62554","t":"tarkib","p":"What allows the verb 'jāʾa' (جَاءَ) to be masculine in 'idhā jāʾaka al-muʾminātu' (إِذَا جَاءَكَ الْمُؤْمِنَاتُ)?","o":["The object 'ka' creates a gap between the verb and the doer.","The doer is a broken plural.","The doer is a linguistic feminine.","The doer is a sound masculine plural."],"e":"The attached pronoun 'ka' (you) acts as a separator (fāṣil), allowing the masculine verb form with a true feminine subject.","s":"al-Shadharah al-Dhahabiyyah · Lesson 10"},{"id":"d9c7750a-23f3-4787-ba80-8b99129ddebd","t":"tarkib","p":"What is the primary grammatical status of the nāʾib al-fāʿil?","o":["Rafʿ (Nominative)","Naṣb (Accusative)","Jarr (Genitive)","Jazm (Jussive)"],"e":"As the subject of a passive sentence, the nāʾib al-fāʿil is an integral component (ʿumdah) and must therefore be in the state of rafʿ.","s":"al-Shadharah al-Dhahabiyyah · Lesson 11"},{"id":"98a1c17a-49bb-4513-9ef3-d5792b7cf2e9","t":"tarkib","p":"How do the verbs of continuity like mā zāla (ما زال) and manfakka (منفك) derive the meaning of 'still'?","o":["By combining a verb of cessation with a negative particle","By indicating a state that occurs only in the morning","By being the opposite of the verb ṣāra","By requiring an ism in the accusative state"],"e":"The base verbs like zāla mean 'to cease'; when combined with the negative particle mā ('not'), the meaning becomes 'did not cease,' which effectively means 'still'.","s":"al-Shadharah al-Dhahabiyyah · Lesson 12"},{"id":"2170deca-5dc9-4381-9f7f-f334f89ab9e9","t":"signs","p":"What is the grammatical effect of the verb kāna (كان) upon the mubtadaʾ and khabar?","o":["It leaves the ism marfūʿ and places the khabar in the state of naṣb","It makes both the ism and the khabar marfūʿ","It makes both the ism and the khabar manṣūb","It places the ism in the state of naṣb and makes the khabar marfūʿ"],"e":"The verb kāna is a nāsikh that abrogates the original rulings of the nominal sentence, keeping the subject (ism) in the nominative state while changing the predicate (khabar) to the accusative state.","s":"al-Shadharah al-Dhahabiyyah · Lesson 12"},{"id":"367fef93-75c0-4760-ac38-8cb2e1eb5430","t":"conjugation","p":"Which temporal category does the fiʿl al-amr (فعل الأمر) logically belong to?","o":["The future tense (al-mustaqbal)","The past tense (al-māḍī)","The present tense (al-ḥāl)","A tense that precedes the past"],"e":"A command is a request for an action to be performed; therefore, it can only be fulfilled in the future relative to the moment the command is given.","s":"Ṣarf 101 · Lesson 10"},{"id":"3d44cd67-5e77-4496-90d9-72f9412d3e78","t":"conjugation","p":"What is the purpose of adding a Hamzat al-Waṣl (همزة الوصل) to the beginning of an imperative verb?","o":["To allow pronunciation of a word starting with a sukūn","To change the meaning to a question","To indicate that the verb is in the plural form","To emphasize the first radical of the verb"],"e":"In Arabic, it is impossible to begin a word with a letter carrying a sukūn; the Hamzat al-Waṣl acts as a prosthetic tool for pronunciation.","s":"Ṣarf 101 · Lesson 10"},{"id":"e32a21ab-ae13-4e19-b22f-8eabd511d61b","t":"conjugation","p":"What is the primary focus of the science of ʿilm al-ṣarf (عِلْمُ الصَّرْف)?","o":["The internal formation and transformation of individual words","The connection of words to form a sentence","The historical evolution of the Arabic script","The rules governing the ending of a word (iʿrāb)"],"e":"Ṣarf is morphology, which examines how individual words are built from root letters and transformed through patterns.","s":"Ṣarf 101 · Lesson 1"},{"id":"26a95839-55a9-4b94-9107-c9d351035f96","t":"voice","p":"The term al-fiʿl al-maʿrūf (الفِعْل المَعْرُوف) refers to which voice of a verb?","o":["Active voice","Passive voice","Command voice","Prohibitive voice"],"e":"Maʿrūf indicates the active voice, where the doer of the action is known or mentioned.","s":"Ṣarf 101 · Lesson 1"},{"id":"38c852fe-a9cb-4c2d-81eb-426481dcd3c7","t":"patterns","p":"In Bāb Naṣara — Yanṣuru (نَصَرَ يَنْصُرُ), what is the technical name for the vowel pattern of the ʿayn position?","o":["Fatḥu Dhammin","Fatḥu Kasrin","Kasru Fatḥin","Ḍammu Dhammin"],"e":"Naṣara has a fatḥah on the ʿayn in the past and a ḍammah in the present, making it Fatḥu Dhammin.","s":"Ṣarf 101 · Lesson 2"},{"id":"25c98429-df81-4c66-a0fb-450c524a2890","t":"patterns","p":"Which bāb is exemplified by the pattern Kasru Fatḥin (كَسْرُ فَتْحٍ)?","o":["Bāb Samiʿa","Bāb Ḍaraba","Bāb Fataḥa","Bāb Ḥasiba"],"e":"Bāb Samiʿa (سَمِعَ يَسْمَعُ) features a kasrah in the māḍī and a fatḥah in the muḍāriʿ on the ʿayn letter.","s":"Ṣarf 101 · Lesson 2"},{"id":"7cc5af72-946b-4c9e-9c62-1ea7abf63ad7","t":"patterns","p":"What does the verb labisa (لَبِسَ) mean when it follows Bāb Samiʿa?","o":["To wear or clothe oneself","To confuse","To travel","To deliver a speech"],"e":"When the root L-B-S follows the fourth bāb (Samiʿa), it refers to wearing clothing, which is the root of the word libās.","s":"Ṣarf 101 · Lesson 3"},{"id":"5692abc2-01c6-4f0b-8f55-e5e794917f64","t":"patterns","p":"How does the meaning of the root L-B-S change when placed on Bāb Ḍaraba as labasa (لَبَسَ)?","o":["It means to confuse or create ambiguity","It means to wear a garment","It means to travel in the land","It means to seal a heart"],"e":"Shifting the root L-B-S to the pattern of Bāb Ḍaraba changes the meaning entirely to confusion or lack of clarity.","s":"Ṣarf 101 · Lesson 3"},{"id":"e8ed436c-6e55-4379-8955-a4274951cb56","t":"conjugation","p":"How does the verb mariḍa (مَرِضَ) differ from saqima (سَقِمَ)?","o":["Mariḍa implies a more severe or weighted sickness, whereas saqima can imply an internal or subtle feeling of being unwell","Mariḍa refers to mental health, while saqima refers to physical health","Saqima refers to a severe disease, while mariḍa is for minor coughs","There is no difference; they are perfect synonyms used interchangeably"],"e":"Arabic distinguishes levels of illness; mariḍa indicates a weighted or serious condition, while saqima often refers to a less severe or internal state of feeling unwell.","s":"Ṣarf 101 · Lesson 4"},{"id":"5b40d8d2-a8bb-403d-9a20-7b9472c4276e","t":"conjugation","p":"What is the semantic nuance of labitha (لَبِثَ) compared to makatha (مَكَثَ)?","o":["Labitha implies becoming stagnant or still in a state or position","Labitha refers to traveling, while makatha refers to staying","Makatha always implies a long duration of centuries","Labitha is exclusively used for objects, not people"],"e":"Labitha, being in Bāb Samiʿa, emphasizes the state of the person remaining stagnant or still, while makatha is more general.","s":"Ṣarf 101 · Lesson 4"},{"id":"b7e877bd-65ae-434a-8d85-935a5b316a39","t":"patterns","p":"What are the vowels on the middle radical (ʿayn al-fiʿl) for the fifth pattern, Karuma Yaqrumu (كَرُمَ يَكْرُمُ)?","o":["Ḍamma in both the māḍī and the muḍāriʿ","Fatḥa in the māḍī and kasrah in the muḍāriʿ","Kasrah in the māḍī and fatḥa in the muḍāriʿ","Fatḥa in both the māḍī and the muḍāriʿ"],"e":"Bāb Karuma is unique because the second radical carries a ḍamma (فَعُلَ يَفْعُلُ) in both the past and present/future tenses.","s":"Ṣarf 101 · Lesson 5"},{"id":"20e30a54-be08-4a0c-b421-486cc2edfd3d","t":"conjugation","p":"What is the meaning of the term 'afʿāl al-ṭabāʾiʿ' (أَفْعَالُ الطَّبَائِعِ)?","o":["Verbs describing inherent, permanent traits of a subject","Verbs related to physical movement","Verbs that require a direct object","Verbs that describe temporary, fleeting states"],"e":"These are verbs of nature that describe qualities like nobility or weakness that define the internal nature (ṭabīʿah) of the individual.","s":"Ṣarf 101 · Lesson 5"},{"id":"2b45b73f-4d4f-46c1-b970-3c9f6e52f686","t":"conjugation","p":"Which particle is used to negate a past tense verb (fiʿl māḍī)?","o":["mā (ما)","lā (لا)","lam (لم)","lan (لن)"],"e":"The particle mā (ما), specifically referred to as mā al-nāfiyah, is used to negate the occurrence of an action in the past tense.","s":"Ṣarf 101 · Lesson 6"},{"id":"2fe35a2b-5098-4ada-8063-c0eaa1b82355","t":"patterns","p":"What is the primary objective of 'implanting' a language into the mind?","o":["To recall vocabulary and patterns without conscious thought","To memorize as many dictionaries as possible","To understand the history of the language","To prepare for advanced artificial intelligence research"],"e":"True mastery is achieved when a speaker can naturally use vocabulary and grammatical patterns without having to think about them before speaking.","s":"Ṣarf 101 · Lesson 6"},{"id":"959bf6cf-800b-471c-bfe0-da5db7175cd6","t":"conjugation","p":"What is the primary linguistic meaning of the term 'muḍāriʿ' (مضارع)?","o":["Resembling (mushābih)","Incomplete action","Ongoing process","Future intention"],"e":"The term muḍāriʿ literally means mushābih (the resembling one) because the imperfect verb resembles the noun (ism) in certain technical aspects.","s":"Ṣarf 101 · Lesson 7"},{"id":"ad3abcbe-8144-4070-bdd3-2bd8eb4e134f","t":"conjugation","p":"Which prefix is used most frequently in the fourteen-form conjugation chart of the muḍāriʿ?","o":["Tā’ (ت)","Yā’ (ي)","Hamzah (أ)","Nūn (ن)"],"e":"The prefix Tā’ is used for eight of the fourteen forms, including all second-person forms and certain third-person feminine forms.","s":"Ṣarf 101 · Lesson 7"},{"id":"0980e9eb-0062-4978-a1e0-8fd5059499f0","t":"conjugation","p":"What does مَا مُنِعُوا mean?","o":["They (m.) were not prevented","They (m.) did not prevent","You two were not prevented","They (m.) were prevented"],"e":"مَنَعَ يَمْنَعُ · باب فَتَحَ\nالماضي المجهول المنفي · جمع مذكر غائب (هُمْ)\nمَا مُنِعُوا = They (m.) were not prevented (passive past, negative)","s":"Ṣarf 101 · Lesson 8"},{"id":"53339282-5ded-40a9-b74c-b9a60a25674d","t":"conjugation","p":"What does مَا حَسُنَ mean?","o":["He was not beautiful","They (f.) were not beautiful","I was not beautiful","You (f. sg.) were not beautiful"],"e":"حَسُنَ يَحْسُنُ · باب كَرُمَ\nالماضي المعلوم المنفي · واحد مذكر غائب (هُوَ)\nمَا حَسُنَ = He was not beautiful (active past, negative)","s":"Ṣarf 101 · Lesson 8"},{"id":"b10f7f8c-9403-4090-bfef-ad09edcf9db4","t":"conjugation","p":"What is the primary function of adding Nūn al-Tawkīd to a present tense verb?","o":["To emphasize that an action will definitely occur in the future","To change the verb from present to past tense","To indicate that the doer of the action is unknown","To shorten the verb for easier pronunciation"],"e":"Nūn al-Tawkīd is used to provide emphasis, ensuring the listener understands the absolute certainty of a future action.","s":"Ṣarf 101 · Lesson 9"},{"id":"020f2b21-bcd6-4b87-851f-b66d688b6516","t":"conjugation","p":"Which form of Nūn al-Tawkīd is characterized by a tashdīd and functions as two Nūns?","o":["al-Thaqīlah","al-Khafīfah","Nūn al-Iʿrāb","Nūn al-Niswah"],"e":"Al-Thaqīlah (the heavy) is a doubled Nūn with a tashdīd, representing two Nūns where the first is silent and the second is voweled.","s":"Ṣarf 101 · Lesson 9"}],[{"id":"8c15669b-2cec-4231-b4b9-141b8dacabe9","t":"sciences","p":"The preservation of the Arabic language was ensured primarily through:","o":["The noble Qur'an and Hadith","Oral traditions alone","Foreign dictionaries","Government decrees"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 1"},{"id":"c74e70b9-6dd9-42d9-81ac-8af369d910d0","t":"sciences","p":"Which Arabic discipline is concerned with the art of effective speaking and public presentation?","o":["Khiṭābah","Qawāfī","Ma’ani","Rasm"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 1"},{"id":"7d43e552-daca-4b8d-8e83-cb05a400be0e","t":"sciences","p":"The term Balaghah collectively refers to which group of disciplines?","o":["Semantics, rhetoric, and literary criticism","Morphology and syntax","Calligraphy and oratory","Prosody and rhyme"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 1"},{"id":"dbdd7e20-05b3-4a18-be23-a45532d21609","t":"sciences","p":"Which of the following is NOT one of the six linguistic meanings of the word \"Nahw\" as mentioned in the poem?","o":["Color","Intention","Amount","Category"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 2"},{"id":"813dacac-0875-4be7-a355-7979edd3fa02","t":"irab","p":"Which word in the sentence \"ضرب زيد عمر\" indicates the doer of the action, and how is this shown?","o":["Zaid (زيد) , by its ending","عمر, by its placement","ضرب, by its root","زيد, by its prefix"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 2"},{"id":"6c141460-16c9-4a6c-9d66-5b330bd30110","t":"irab","p":"In the sentence \"ضرب زيد عمر\", what grammatical role does \"عمر\" play?","o":["Recipient of the action","Predicate","Doer of the action","Preposition"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 2"},{"id":"d41b1214-c9dd-4b8f-9046-8d4ee6266af9","t":"irab","p":"The Basriyyoon would create new rules for every rare linguistic exception they encountered.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 4"},{"id":"a6c87564-0d29-4f7b-afdc-b8c2464f19e1","t":"irab","p":"Which of the following is excluded from being kalām due to the absence of articulation?","o":["A meaningful gesture","A composed Arabic sentence","A spoken phrase","An utterance with implied meaning"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 6"},{"id":"2115cd08-ba5e-45ac-9e5c-9a3085e001dc","t":"irab","p":"Which of the following is *not* a necessary condition for a word to be classified as an ism (اسم) in Arabic grammar?","o":["It must refer to a physical object","It conveys a meaning in itself","It is not associated with any tense","It can function independently of other words"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 7"},{"id":"c599e81c-17ff-46eb-b032-72baa809314c","t":"irab","p":"True or False: An ism can only refer to physical, tangible objects.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 7"},{"id":"6252e349-142c-442b-8cf6-14c98c9334b1","t":"irab","p":"The word ضَرْبٌ (striking) is classified as which of the following?","o":["Noun (ism اسم)","Verb (fiʿl فِعْل)","Particle (ḥarf حَرْف)","Imperative"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 8"},{"id":"0cfe6ebd-8837-43e7-aa6a-1c0b2d04dece","t":"irab","p":"Which example best illustrates the function of the particle فِي?","o":["Containment or location","Negation","Interrogation","Command"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 8"},{"id":"3f33bbcd-92ca-4011-83dd-88bb69841f9e","t":"signs","p":"Which of the following is NOT one of the four primary signs of a noun in Arabic grammar as discussed in this lesson?","o":["Tashbīh (تشبيه)","Genitive case (الخفض)","Nunation (التنوين)","The definite article (الـ)"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 10"},{"id":"8092b7ee-e038-4a68-8851-cfc423e53682","t":"irab","p":"Which particle of oath is restricted to only entering upon the Divine Name (لفظ الجلالة)?","o":["تَـ (ta)","وَ (wa)","بِـ (bi)","كَـ (ka)"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 10"},{"id":"4d83baa1-34dc-4fb3-93f6-04cb4abb5080","t":"signs","p":"The presence of the definite article (الـ) at the beginning of a word is a sign that the word is a noun.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 10"},{"id":"db55bd7c-492f-47d0-9251-fe2eb9ce4bc4","t":"signs","p":"Which particle is a distinguishing sign of the verb because it only enters upon verbs and never upon nouns or particles?","o":["قَدْ (qad)","سَـ (sīn)","تاء التأنيث الساكنة","سوف (sawfa)"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 11"},{"id":"0ae9f835-97bf-4855-9572-b957b671834a","t":"irab","p":"The particle قَدْ (qad) can enter upon both past and present tense verbs.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 11"},{"id":"759a564d-0d45-4e03-a07c-f32938d734c9","t":"irab","p":"Which of the following best describes the definition of إعراب (iʿrāb)?","o":["Changing the ending of words due to different grammatical influencers, either in pronunciation or assumption","Changing the meaning of a word based on context","Adding prefixes to words for emphasis","Using synonyms to replace words in a sentence"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 14"},{"id":"5f620ce8-e1fe-43b5-aa4f-0fdf981a5b79","t":"irab","p":"The grammatical influencer (عامل) determines whether a noun is a subject, object, or in another role.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 14"},{"id":"be1cbbab-d829-4659-b47b-63df26cd0122","t":"irab","p":"In the first person, how does the فعل مضارع distinguish between genders?","o":["There is no gender distinction","By using different prefixes","By using different suffixes","By vowel changes"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 17"},{"id":"0b89df82-900a-496a-b909-adb7fb0000f0","t":"irab","p":"In the nominative state, the word \"حَمَّامَاتٌ\" is marked by:","o":["A visible ḍammah","An estimated ḍammah","A wāw","An alif"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 18"},{"id":"a18ff9f8-6f11-4155-997e-5983882d0757","t":"signs","p":"Which of the following is NOT a context in which the ḍammah is estimated rather than visible?","o":["Sound masculine plural","Maqṣūr noun","Defective noun","Noun with yāʾ al-mutakallim"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 18"},{"id":"f4217406-2f78-43b9-8710-5ef1d02ec4ef","t":"irab","p":"The nominative state in Arabic is always marked by a visible ḍammah.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 18"},{"id":"f6b4fe8a-53b6-419c-8490-50e70a5b5a07","t":"irab","p":"The present tense verb in Arabic always begins with one of the four letters: hamzah, nūn, yāʾ, or tāʾ.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 19"},{"id":"f73a3211-613b-4ec1-a52e-e1992b102a91","t":"signs","p":"Which of the following is NOT one of the five special nouns (al-asmāʾ al-khamsah)?","o":["كِتَابٌ","أَبٌ","أَخٌ","ذُو"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 20"},{"id":"d6c76e84-40ac-44f6-a801-f1ba0c75230a","t":"signs","p":"How is the nominative case signaled for the five special nouns when all conditions are met?","o":["By a wāw","By a ḍammah","By an alif","By a yāʾ"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 20"},{"id":"b2f44560-ca72-4c44-9fe8-b2c44acdb373","t":"signs","p":"What is the function of the nūn at the end of a dual noun in the nominative case?","o":["It substitutes for tanwīn","It indicates the verb tense","It marks the accusative case","It signals feminine gender"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 21"},{"id":"4e14dc3e-a1a4-401f-8ee1-4667797f9674","t":"signs","p":"Which of the following endings marks the nominative dual in Arabic?","o":["ـَانِ","ـَتَا","ـُوْنَ","ـَيْنِ"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 21"},{"id":"a20ca841-2f24-4afe-937f-456c5ba0b827","t":"irab","p":"What is the grammatical term for the process where one marker replaces another to indicate the same grammatical meaning?","o":["Niyābah","Iʿrāb","Iʿjām","Tashkīl"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 21"},{"id":"e2b1e166-5dbc-49bc-8761-fe384e830582","t":"mansubat","p":"Which of the following is a broken plural (jamʿ al-taksīr) that takes an estimated fatḥah for naṣb?","o":["سُكَارَى","الْمُعَلِّمُونَ","مُسْلِمَاتٌ","كِتَابَانِ"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 22"},{"id":"e8c5fb2c-ed2d-4e8c-bb12-e92c1c1b9915","t":"mansubat","p":"Which of the following is NOT a context where the fatḥah is the sign of naṣb?","o":["Dual noun","Singular noun","Broken plural","Present tense verb preceded by a naṣb particle"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 22"},{"id":"61c44708-4460-4142-a862-fcbab38b38cb","t":"mansubat","p":"The fatḥah is always visible when marking naṣb on a singular noun.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 22"},{"id":"f89e3d2a-6131-492e-9074-3174c8a07315","t":"irab","p":"What is the accusative marker in the word «مُسْلِمِينَ»?","o":["Yāʾ","Fatḥah","Alif","Kasrah"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 23"},{"id":"45f7dab0-2728-4c23-9551-3c845d79ee2d","t":"irab","p":"In the example «نَصَحْتُ الْمُجْتَهِدِينَ», why is the word «الْمُجْتَهِدِينَ» in the accusative case?","o":["It is the object of the verb","It is the subject","It is in the genitive state","It is the predicate of a nominal sentence"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 23"},{"id":"e522838e-0b0f-4bf1-85bf-7671eed69397","t":"signs","p":"Which of the following is the original (aṣl) sign of khafḍ (jarr) in Arabic grammar?","o":["Al-kasrah","Al-yāʾ","Al-fatḥah","Al-dammah"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 25"},{"id":"f0d818c1-55f7-485e-a89f-ffba7f2e5456","t":"signs","p":"The fatḥah can serve as the sign of khafḍ for sound feminine plural nouns.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 25"},{"id":"20a8791e-7ae5-4575-b1f4-11a40e2bb01d","t":"irab","p":"Jazm (جزم) applies exclusively to which type of verb?","o":["Present tense verbs","Past tense verbs","Imperative verbs","Verbal nouns"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 27"},{"id":"3bdd8b1a-11b2-4d92-917c-1024b7aca848","t":"signs","p":"Which of the following is not a category of al-muʿrabāt (المعربات) that is declined by letters?","o":["Broken plural","Dual","Sound masculine plural","Five nouns"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 27"},{"id":"47bcc287-eb2c-4c0f-86a4-7ff6a143e0dd","t":"irab","p":"The attached pronouns (ألف، واو، ياء) in the five verbs function as:","o":["Subjects (fāʿil)","Direct objects","Indirect objects","Prepositions"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 27"},{"id":"eb0dcb45-4d9a-4e33-9083-1147801162b8","t":"irab","p":"Which verb form is declinable (معرب) by default in Arabic grammar?","o":["Present tense verb","Past tense verb","Imperative verb","All verb forms"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 29"},{"id":"a8653b17-c463-4b6c-820b-a77121b52d38","t":"irab","p":"The past tense verb in Arabic is always indeclinable, regardless of its position in a sentence.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 29"},{"id":"86e0573b-8112-41b2-9bc5-f3479944223a","t":"irab","p":"Which of the following is NOT a necessary condition for a noun to be a fāʿil (الفاعل) in Arabic grammar?","o":["It must be definite","It must be a noun (ism)","It must be in the nominative case (marfūʿ)","It must be preceded by its verb"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 36"},{"id":"7a0e093e-8462-4e1d-8e2e-85a70e8bb289","t":"irab","p":"What is excluded from being a fāʿil by the requirement of being in the nominative case?","o":["Nouns in the accusative or genitive","Conjugated verbs","Explicit nouns","Proper names"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 36"},{"id":"ed329ee9-991b-431b-a015-855774843590","t":"irab","p":"Which grammatical case must the apparent fāʿil always be in?","o":["Nominative","Accusative","Genitive","Jussive"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 37"},{"id":"e09a20e1-761e-4e77-ab04-6b84f28178aa","t":"irab","p":"The apparent fāʿil can only be a singular noun.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 37"},{"id":"59e1ef9d-ec1c-4d1b-96ea-c536eeaca5da","t":"irab","p":"A noun annexed to the first-person singular pronoun (yā’ al-mutakallim) as fāʿil has an estimated ḍammah in the nominative case.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 37"},{"id":"f247b26a-ac8e-445b-8bce-a3c591c733d1","t":"sciences","p":"What is the morphological change to a past tense verb in the passive voice?","o":["First letter takes ḍammah, letter before the last takes kasrah","First letter takes fatḥah, letter before the last takes sukūn","First letter takes kasrah, last letter takes ḍammah","First letter takes sukūn, letter before the last takes fatḥah"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 38"},{"id":"09050c6a-92fb-4bcf-bb28-ba715dcdb0bb","t":"irab","p":"What is the Arabic grammatical term for “verbs of the heart” as described in this lesson?","o":["Afʿāl al-qulūb (أَفْعَالُ الْقُلُوبِ)","Afʿāl al-lisān","Afʿāl al-ʿaql","Afʿāl al-jawāriḥ"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 42"},{"id":"9d341abf-bbaa-436b-b02c-98bf0b17afa3","t":"irab","p":"Which of the following best defines a definite noun (معرفة maʿrifah) in Arabic grammar?","o":["A word that points to a specific, known referent","A word that refers to any member of a group","A noun that cannot accept the definite article","A noun used only in iḍāfah constructions"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 44"},{"id":"19b51a34-c413-406a-b793-7d1b4ccd2bc5","t":"signs","p":"What is the grammatical case assigned to nouns that serve as faḍalāt (فَضَلَات) in Arabic syntax?","o":["Accusative","Nominative","Genitive","Vocative"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 48"},{"id":"2f7e2813-0c5c-41b0-99c8-42977ac67267","t":"irab","p":"The core pillars (ʿumad) of an Arabic sentence are always in the accusative case.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 48"},{"id":"f2ccad99-d58f-4e9d-8183-0d0e5e9a7064","t":"mansubat","p":"Which of the following best describes the primary function of al-ḥāl (الحال) in Arabic grammar?","o":["To clarify ambiguity regarding states or manners","To specify the essential identity of a noun","To indicate the tense of a verb","To denote possession"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 50"},{"id":"911a4360-15e6-4109-bb6a-e245b2037fce","t":"mansubat","p":"In the dual form لَقِيتُ عَبْدَ اللَّهِ رَاكِبَيْنِ, what does the dual ḥāl clarify?","o":["That both the speaker and ʿAbd Allāh are riding","That only the speaker is riding","That only ʿAbd Allāh is riding","That neither is riding"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 50"},{"id":"49ded19a-d122-4e9a-9b3a-872a160d9cea","t":"mansubat","p":"The removal of al-ḥāl from a sentence leaves the sentence grammatically complete.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 50"},{"id":"bbb0efdd-1cb4-471c-9c53-496514f5d963","t":"mansubat","p":"Which of the following best defines al-tamyīz in Arabic grammar?","o":["An accusative noun clarifying ambiguity in entities or relations","A verb clarifying a sentence","A prepositional phrase explaining a verb","An adjective describing a noun"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 51"},{"id":"021ad995-6286-4ac1-86ae-d72cd91d7c18","t":"mansubat","p":"Tamyīz can be realized through verbs and particles.","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 51"},{"id":"3088f86b-dc05-4d0d-8ca8-75fb18e687f4","t":"mansubat","p":"The primary objective of al-tamyīz is to remove ambiguity from a sentence.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 51"},{"id":"799517b9-e547-43d0-a80b-3baf2561e331","t":"mansubat","p":"What is the grammatical status of the proper noun munādā in the dual form?","o":["Built on alif","Built on wāw","Built on ḍammah","Accusative"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 54"},{"id":"9487b22e-4627-465c-902a-37c43909d5b3","t":"mansubat","p":"The munādā is always introduced by the particle يَا (yā).","o":["False","True"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 54"},{"id":"ea79d487-6841-4416-814a-c47961226f55","t":"mansubat","p":"A proper noun munādā never takes tanwīn.","o":["True","False"],"e":"","s":"al-Tuḥfat al-Saniyyah · Lesson 54"}],[{"id":"ca6353d3-4dd6-40aa-affe-4e0e216dfb80","t":"advanced","p":"What is the primary source of linguistic evidence (shawāhid) used in the Mutammimah for beginner students?","o":["Qurʾānic verses","Pre-Islamic Arabic poetry","Prophetic narrations (Ḥadīth)","Proverbs of the Arabs"],"e":"The author prioritizes Qurʾānic verses as examples to provide students with familiar contexts before introducing complex poetry.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 1"},{"id":"b586b9e2-09e6-435e-9dde-b7f6e98db2d9","t":"nuhat","p":"Who is traditionally recognized as the first person to codify the rules of Arabic grammar under the guidance of ʿAlī ibn Abī Ṭālib رضي الله عنه?","o":["Abū al-Aswad al-Duʾalī","Sībawayh","Al-Khalīl ibn Aḥmad","Ibn Mālik"],"e":"Abū al-Aswad al-Duʾalī is the founder of naḥw, having been commanded to follow the path (unḥu hādhā al-naḥw) laid out by ʿAlī رضي الله عنه.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 2"},{"id":"feb92d44-08bc-4398-80ea-2ec95dc6ed68","t":"advanced","p":"Why do some grammarians define kalām before defining the individual word (kalimah)?","o":["Because the primary goal of Naḥw is iʿrāb, which only occurs in a sentence","Because kalām is shorter to define","Because words do not have meanings outside of a sentence","Because the word is logically prior to the sentence"],"e":"The objective of the grammarian is to understand iʿrāb, and since iʿrāb is a function of the relationships between words in a sentence, the sentence is the primary subject of the science.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 3"},{"id":"e0e22dd5-8a77-449b-8f9f-17a56e3946b7","t":"advanced","p":"What is the minimum number of words required to form a valid instance of kalām?","o":["Two words","One word","Three words","Four words"],"e":"Valid speech requires both a subject (musnad ilayh) and a predicate (musnad), which requires at least two nouns or a verb and a noun.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 4"},{"id":"a8c0bf0d-9505-42b9-83c8-cccb611db62b","t":"advanced","p":"What is the primary distinction of an ism (إسم) in its definition?","o":["It indicates a meaning in itself and is not joined to a tense by coinage.","It indicates a meaning in itself and is joined to a tense.","It indicates a meaning in something else and is joined to a tense.","It indicates a meaning in something else and is not joined to a tense."],"e":"An ism is defined as indicating a meaning in itself (fī nafsihī) without being inherently attached to one of the three tenses by coinage (waḍʿan).","s":"Mutammimah al-Ājurrūmiyyah · Lesson 5"},{"id":"dfb375bd-c929-4a36-bd27-de0258974c3b","t":"advanced","p":"Why is a verb unable to be a musnad ilayh (subject of predication)?","o":["Because it indicates an action (ḥadath), which is itself information","Because it is always followed by a particle","Because it lacks a fixed phonetic ending","Because it cannot be dualized or pluralized"],"e":"Information is predicated of an entity (dhāt); since a verb indicates an action (information) and time, one cannot give information about information.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 6"},{"id":"5196f116-eab2-454d-99d4-8ea99ffa0e61","t":"advanced","p":"Why does the dhāl in yawma'idhin (يومئذ) carry a kasrah?","o":["To prevent the meeting of two quiescent letters (sākinayn)","Because it is a muḍāf ilayh","Because it is a sign of its indeclinability","Because of the influence of the word yawm"],"e":"The dhāl is originally sākin, and the tanwīn is a nūn sākinah; the dhāl receives a kasrah to allow for the pronunciation of the tanwīn.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 7"},{"id":"48ee8980-53ad-416e-a544-c7bc58781f01","t":"advanced","p":"What is the primary semantic contribution of the particle qad (قد) when it precedes a māḍī (past tense) verb?","o":["Taḥqīq (Certainty/Realization)","Taqlīl (Rarity)","Taswīf (Delaying)","Jazm (Apocopation)"],"e":"When qad enters upon the māḍī, it signifies taḥqīq, denoting the definitive realization or confirmation of the action.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 8"},{"id":"f732559e-8b42-4eb0-8aea-147b6776c2d1","t":"advanced","p":"In the sentence 'mā aḥsana zaydan!', what does the naṣb on the name Zayd indicate?","o":["An expression of astonishment (taʿajjub)","A question about Zayd's beauty","A negation that Zayd did good","A possessive relationship"],"e":"The naṣb on the object indicates astonishment or wonder in this specific structural pattern.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 9"},{"id":"d15183f3-db95-4378-990a-ff41b51e0c43","t":"advanced","p":"Which type of resemblance is found in the interrogative noun 'matā' (مَتَى)?","o":["Shibhu al-Maʿnawī (Semantic)","Shibhu al-Wadaʿī (Constructional)","Shibhu al-Istiʿmālī (Functional)","Shibhu al-Iftiqārī (Dependent)"],"e":"It carries the meaning of interrogation or conditioning, which are functions traditionally assigned to letters.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 10"},{"id":"953db94b-a480-4b8a-8e56-468a5eb891b7","t":"advanced","p":"For the word amsi (أمسِ) to be mabnī upon kasrah, which condition must be met?","o":["It must refer specifically to the day preceding the current day","It must have the Alif-Lām attached","It must be used in its plural form","It must be used in the diminutive form (taṣghīr)"],"e":"Amsi is only mabnī when it refers specifically to 'yesterday'; if it is pluralized, made diminutive, or has the Alif-Lām, it becomes muʿrab.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 11"},{"id":"1bd1e61b-77e9-4ab3-9d82-dca2b2a65f67","t":"nuhat","p":"What is the default state of the verb (fiʿl) according to the Baṣran school of grammar?","o":["Mabnī (Indeclinable)","Muʿrab (Declinable)","Majzūm (Jussive)","Marfūʿ (Nominative)"],"e":"The Baṣran school holds that because two out of three categories of verbs (māḍī and amr) are mabnī, indeclinability is the original state (aṣl) for verbs.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 12"},{"id":"252de7ad-f137-4c43-a7fe-3e6ccf5587ec","t":"advanced","p":"Why is the verb 'yaktubunna' (يَكْتُبُنَّ) considered muʿrab rather than mabnī?","o":["Because the wāw of plurality is a separator taqdīran (assumed)","Because it is in the state of rafʿ","Because the nūn is a root letter","Because it is preceded by a hidden agent"],"e":"Although the wāw is dropped due to the meeting of two unvoweled letters, it functions as a separator, preventing the composition (tarkīb) required for bināʾ.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 13"},{"id":"1264c0bb-60f5-4b47-b15a-7ce95cd14c01","t":"advanced","p":"The grammatical term nazʿ al-khāfiḍ (نَزْعُ الْخَافِضِ) refers to which scenario?","o":["The removal of a preposition causing a noun to revert to naṣb","The addition of a second subject","The change of a verb from past to present","The doubling of a root letter"],"e":"Nazʿ al-khāfiḍ is the removal of a preposition, which results in the following noun taking the accusative state (naṣb) as it returns to its original position relative to the verb.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 14"},{"id":"29772cdf-56b5-4784-b4fa-533a4e632c26","t":"advanced","p":"What is the primary function of the alif (ألف) as a sign of iʿrāb?","o":["To act as a substitute for ḍammah in the state of rafʿ for dual nouns","To represent the state of naṣb in singular nouns","To serve as the subject (fāʿil) in all past tense verbs","To indicate the feminine gender in sound feminine plurals"],"e":"The alif serves as a secondary sign of rafʿ specifically for the muthannā (dual) and those words treated as dual (mulḥaq).","s":"Mutammimah al-Ājurrūmiyyah · Lesson 15"},{"id":"1e9c0111-e22d-4d80-b637-41cf774b9f07","t":"advanced","p":"If the word 'kull' (كل) is muḍāf to a unit of time (ẓarf), what is its grammatical role?","o":["Mafʿūl fīhi","Mafʿūl muṭlaq","Mafʿūl bihi","Mafʿūl lahu"],"e":"When 'kull', 'baʿḍ', or a number is attached to a ẓarf, it takes the role of an adverb (mafʿūl fīhi).","s":"Mutammimah al-Ājurrūmiyyah · Lesson 16"},{"id":"fcb3d8b0-265f-42b6-ada8-6a3669fe28d9","t":"advanced","p":"Why does the word ʿArafātin (عَرَفَاتٍ) accept tanwīn despite being a feminine proper name?","o":["It is tanwīn al-muqābalah","It is fully declinable (munṣarif)","It is a broken plural","It is a masculine plural"],"e":"The tanwīn in sound feminine plurals is called tanwīn al-muqābalah, which corresponds to the nūn in sound masculine plurals, and does not indicate full declension (ṣarf).","s":"Mutammimah al-Ājurrūmiyyah · Lesson 17"},{"id":"0a2a0e51-47ff-4b4f-b7d9-023faf3fba8e","t":"advanced","p":"Which of the following word types is declined by vowels (ḥarakāt) as the primary method?","o":["The broken plural (jamʿ taksīr)","The dual (muthannā)","The sound masculine plural","The six nouns (asmāʾ sittah)"],"e":"Broken plurals, singular nouns, sound feminine plurals, and the standard present tense verb are the four categories declined by vowels.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 18"},{"id":"4d6e88e9-d27a-4c86-bfec-e8a59cc77630","t":"advanced","p":"Which dialect is considered the most eloquent (afṣaḥ) regarding the noun 'han'?","o":["Naqṣ (shortening by dropping the final letter)","Itmām (complete inflection with letters)","Qaṣr (fixing with an alif)","Ibdāl (substitution of letters)"],"e":"In the dialect of naqṣ, the final weak letter of 'han' is dropped and it is inflected with standard vowels on the nūn, which is the most eloquent usage for this specific noun.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 19"},{"id":"cb1438fb-f9e9-4165-bd4c-5b871eec4fcc","t":"advanced","p":"What is the primary reason an ism becomes ġayr munṣarif?","o":["It resembles a verb (fiʿl) in two distinct ways.","It resembles a particle (ḥarf) in its meaning.","It is derived from a foreign language only.","It is a plural that cannot be simplified."],"e":"A noun becomes ġayr munṣarif when it resembles a verb from two perspectives (formal and semantic), making it 'heavy' and secondary.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 20"},{"id":"388f1c55-5a8a-443a-bd92-c7a9d1b66ca2","t":"advanced","p":"Which morphological patterns are associated with real deviation (al-ʿadl al-taḥqīqī) in numerical nouns?","o":["Fuʿāl and Mafʿal","Faʿʿāl and Mafʿal","Fuʿal and Fāʿil","Afʿal and Fuʿlā"],"e":"Real deviation is observed in numerical words like Uḥād (Fuʿāl) and Mawḥad (Mafʿal), which represent the original number repeated twice.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 21"},{"id":"529ffe94-e168-4aa2-8e04-794327cf20d7","t":"advanced","p":"Which term describes giving tanwīn to a diptote to match the rhyme or rhythm of preceding verses in the Qur’an?","o":["Tanāsub","Ḍarūrah al-shiʿriyyah","Al-talmīḥ","Ujmah"],"e":"Tanāsub refers to phonetic or rhythmic symmetry, such as when a ghayr munṣarif word receives tanwīn to match the ending of surrounding verses.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 22"},{"id":"9b20b43d-3aac-472d-b9a0-370e17cb997e","t":"advanced","p":"Which of the following describes a pronoun that has no physical form or visible image in the utterance?","o":["Al-Ḍamīr al-Mustatir","Al-Ḍamīr al-Muttaṣil","Al-Ḍamīr al-Bāriz","Al-Ḍamīr al-Munfaṣil"],"e":"A hidden pronoun (al-mustatir) is defined as that which has no visible form (ṣūrah) in the wording, being assumed conceptually.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 23"},{"id":"0da7848f-3d83-4222-b423-9d406d176356","t":"advanced","p":"Which of the following defines the proper noun (al-ʿalam)?","o":["A noun that designates its referent absolutely without a linguistic hint (qarīnah)","A noun that becomes definite through the addition of alif-lām","A noun that requires a relative clause (ṣilah) to identify its referent","A noun that only indicates a genus understood in the mind"],"e":"Unlike other definite nouns that require hints like gestures or prefixes, the ʿalam identifies its referent inherently by its coinage.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 24"},{"id":"e9b94e87-5d8f-4f85-a198-d4363dfdeb65","t":"advanced","p":"Why was a 'wāw' historically added to the plural indicative noun 'ulāʾi' (أُولَاءِ)?","o":["To distinguish it from the preposition 'ilā' (إِلَى) in early manuscripts","To indicate that the word is feminine","To signify the plural nature of the word","To facilitate a specific dialectal pronunciation"],"e":"The non-pronounced wāw was an orthographic device to differentiate the indicative noun from similar-looking prepositions or particles.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 25"},{"id":"92e1869b-16af-446f-a26d-dbf9d60dad87","t":"advanced","p":"Which of the following is a condition for 'dhā' (ذَا) to be an ism mawṣūl?","o":["It must be preceded by an interrogative 'mā' or 'man'","It must be used to mean 'owner of'","It must be followed by a single noun","It must be the first word in the sentence"],"e":"For 'dhā' to be a relative noun, it must be preceded by the interrogative 'mā' or 'man' and followed by a full relative clause.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 26"},{"id":"7fc45cc9-0b99-46ec-8dc6-c4a945644089","t":"advanced","p":"What does 'riʿāyat al-lafẓ' refer to when using shared relative pronouns like man (مَنْ)?","o":["Matching the pronoun to the literal singular masculine form","Matching the pronoun to the intended plural meaning","Matching the pronoun to the gender of the subject","Following the rhyme of the surrounding verses"],"e":"Riʿāyat al-lafẓ involves maintaining grammatical agreement with the literal singular masculine word-form of the shared relative pronoun.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 27"},{"id":"54653b80-aebb-41a9-8957-42619a860099","t":"advanced","p":"Which category of Alif-Lām is found in the proper name 'al-Yasaʿ' (اليسع)?","o":["al-Zāʾidah al-Lāzima (Inseparable extra)","al-Zāʾidah Ghayr Lāzima (Separable extra)","al-Mawṣūlah (Relative)","al-Muʿarrifah (Defining)"],"e":"Proper names like al-Yasaʿ and as-Samawʾal were coined with the Alif-Lām as an inseparable part of the name from the beginning.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 28"},{"id":"8e39ce19-d743-432c-a7b4-d2ad0bcf1265","t":"advanced","p":"What is the meaning of an ism mu’awwal (اسم مؤول) functioning as a fā’il?","o":["A structure (like an + verb) reinterpreted as a single noun (maṣdar)","A noun that is actually a hidden pronoun","A noun that is physically present in the text","A noun that has been moved to the end of the sentence"],"e":"An ism mu’awwal refers to structures using particles like 'an' or 'anna' that are grammatically reinterpreted as a maṣdar (verbal noun) to fulfill the role of the fā’il.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 29"},{"id":"535f7dcb-34f8-4b72-a771-1392c747f042","t":"advanced","p":"In the verse 'Mā la-nā min shāfiʿīn' (ما لنا من شافعين), what is the grammatical position of 'shāfiʿīn'?","o":["Majrūr lafẓan and marfūʿ maḥallan as a mubtadaʾ","Majrūr lafẓan and manṣūb maḥallan","The predicate (khabar) of the sentence","A fāʿil for a hidden verb"],"e":"The word is literally genitive (majrūr) due to the redundant 'min' but occupies the nominative position (maḥall) of the mubtadaʾ.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 31"},{"id":"afe70f44-da1d-489f-9a88-5df95ff3bc04","t":"advanced","p":"Which condition must be met for the verb Dāma (دام) to govern as a sister of Kāna?","o":["It must be preceded by Mā al-Masdariyyah al-Ẓarfiyyah.","It must be preceded by a particle of negation (nafī).","It must be preceded by an oath (qasam).","It must be in the present tense (muḍāriʿ) form."],"e":"Dāma only governs when preceded by Mā al-Masdariyyah al-Ẓarfiyyah, which turns the verb into a maṣdar and adds the meaning of duration (muddah).","s":"Mutammimah al-Ājurrūmiyyah · Lesson 33"},{"id":"1ccd80b0-41ab-49c0-a080-d8a48e2d0733","t":"advanced","p":"What is the primary function of Lākinna (لَكِنَّ)?","o":["Istidrāk (Rectification)","Tarajjī (Hope)","Tamannī (Wishing)","Tashbīh (Resemblance)"],"e":"Lākinna is used for istidrāk, which involves correcting a potential misconception arising from a previous statement or transitioning between opposites.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 35"},{"id":"9a808367-2b51-47af-9453-e21ef7f728e8","t":"advanced","p":"What is the primary function of the lā al-nāfiyah li al-jins (لا النافية للجنس)?","o":["To categorically negate the entire class or genus","To negate a single unit while allowing for more","To prohibit an action from occurring","To emphasize a preceding negation"],"e":"Its purpose is tanṣīṣ (explicit specification) of negation for the entire category, leaving no possibility for even one individual to be included in the attribution of the predicate.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 37"},{"id":"dc096950-e7ab-4716-8884-7a5b58fe6270","t":"advanced","p":"What is the primary grammatical function of Ẓanna (ظَنَّ) and its sisters?","o":["They give naṣb to both the original subject and predicate as two objects","They raise the subject and give naṣb to the predicate","They give naṣb to the subject and raise the predicate","They turn the subject into a fāʿil and the predicate into a ḥāl"],"e":"Ẓanna and its sisters enter a nominal sentence and transform both the mubtadaʾ and khabar into objects (mafʿūlayn) in the naṣb case.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 38"},{"id":"4f6b56e7-5f10-401c-8c99-e29f1cc9c0d5","t":"advanced","p":"Why is 'yawman' in the verse 'yakhāfūna yawman' (يخافون يوماً) considered a mafʿūl bihi rather than a mafʿūl fīhi?","o":["Because the day itself is the object of fear, not the time in which fear occurs","Because it is an unspecified time period","Because it follows a verb that cannot govern a ẓarf","Because the noun is definite (maʿrifah)"],"e":"The fear is directed at the day itself; the action is not taking place 'inside' the day as a container.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 41"},{"id":"78311a01-649f-4606-a3f1-ff661fd6e0e9","t":"advanced","p":"Why is naṣb mandatory for 'al-jabala' in the phrase 'Sirtu wa-l-jabala' (سرتُ والجبلَ)?","o":["Because it is logically impossible for a mountain to participate in the act of traveling","Because the word 'al-jabal' is definite","Because the wāw is strictly a conjunction","Because the verb requires two objects"],"e":"Since a mountain cannot share in the action of traveling alongside the subject, conjunction (ʿaṭf) is impossible, requiring the noun to be a mafʿūl maʿahu in the accusative case.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 42"},{"id":"8b4bf2d9-977b-47a5-9454-4a25da10e1ef","t":"advanced","p":"What is the technical meaning of 'faḍlah' (فضلة) in Arabic grammar?","o":["An element that is not one of the two primary pillars (musnad and musnad ilayh)","A word that is extra and adds no meaning to the sentence","A word that must always be removed from the sentence","A synonym for the predicate (ẖabar)"],"e":"A faḍlah is any part of the sentence that is not a primary pillar, though it is often essential for the intended meaning.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 43"},{"id":"0f50b7c5-0653-4180-8fc7-386d546576ca","t":"advanced","p":"What is the primary technical purpose of the tamyīz (تمييز)?","o":["To clarify the ambiguity (ibhām) in an essence or relationship","To specify the time an action occurred","To describe the state of the agent during the action","To provide a reason for the occurrence of a verb"],"e":"The tamyīz is defined as the noun that interprets or clarifies what is vague regarding essences (dhawāt) or attributions (nisab).","s":"Mutammimah al-Ājurrūmiyyah · Lesson 44"},{"id":"5f07cd53-f83c-4e0c-a1ee-2d7304133d4e","t":"advanced","p":"If the tool khalā (خَلَا) is preceded by mā al-maṣdariyyah, what is the required case of the following noun?","o":["mandatory naṣb","mandatory jarr","optional rafʿ","optional naṣb or jarr"],"e":"Mā al-maṣdariyyah only precedes verbal sentences; therefore its presence forces khalā to be a verb, making the following noun the object (mafʿūl bihi) in naṣb.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 45"},{"id":"0d097757-0b28-4847-8622-0de09cf8ea97","t":"advanced","p":"What is the primary meaning of the particle min (مِنْ)?","o":["ibtidāʾ al-ghāyah (the starting point)","intihāʾ al-ghāyah (the end point)","istiʿlāʾ (superiority)","tashbīh (resemblance)"],"e":"The primary meaning of min is to indicate the beginning or starting point of an action or limit.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 46"},{"id":"98b168c8-c55a-49c6-8dff-ad79571f0ec5","t":"advanced","p":"If the particle An (أن) is preceded by a verb of certainty (ʿilm), what is its grammatical status?","o":["It is Mukhaffafah min al-Muthaqqalah and the verb remains marfūʿ.","It is An Maṣdariyyah and governs Naṣb.","It is An Tafsiriyyah and does not govern.","It is An Zā'idah and has no meaning."],"e":"When preceded by certainty, it is the lightened form of 'Anna', its subject is hidden, and the following verb is marfūʿ as part of the predicate sentence.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 48"},{"id":"1ebba843-ef86-4c30-aede-212d96ad6df4","t":"advanced","p":"What is the sign of jazm in the verb 'aṣhu' (أَصْحُ) in the poetic line 'alammā aṣhu'?","o":["The removal of the final wāw","Sukūn","The presence of a hidden nūn","The presence of a fatḥah"],"e":"The verb was originally 'aṣhū' (أَصْحُو); the final weak letter (wāw) was dropped as the sign of jazm.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 49"},{"id":"6b45a055-d57f-41ae-a416-2eaa08bc78d3","t":"advanced","p":"What is the primary meaning of the particle wāw (و)?","o":["Unconditional gathering (mutlaq al-jamʿ)","Sequence and immediate succession","Sequence with a delay","Choice between two options"],"e":"The wāw indicates only that two things are associated in a ruling without specifying order, delay, or simultaneity.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 51"},{"id":"bd2376aa-f118-4504-949c-9d26d2eb4bd8","t":"advanced","p":"What is the primary function of ‘tarākhī rutabī’ in the usage of the particle thumma (ثُمَّ)?","o":["To show that the second item is of a significantly higher rank or level","To indicate a long temporal gap between events","To suggest that the second action occurs immediately","To negate the possibility of the second item occurring"],"e":"Tarākhī rutabī indicates a delay in status or rank rather than time, showing that the second mentioned item is superior or more important than the first.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 52"},{"id":"2382702c-a0be-47e1-a8ff-bd4f4c479dee","t":"advanced","p":"What is the most eloquent (afṣaḥ) way to emphasize a dual noun using al-nafs (النفس)?","o":["Using the plural pattern afʿul: anfusahumā","Using the singular form: nafsahumā","Using the dual form: nafsāhumā","Omitting the pronoun"],"e":"While other forms exist, the standard and most eloquent classical Arabic usage is to pluralize the emphasis word on the pattern of afʿul for dual nouns.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 53"},{"id":"3451c59d-a26c-4230-b0ca-3fdccfb3a12b","t":"advanced","p":"What grammatical role does the noun following a governing Ism al-Mafʿūl (اِسْمُ الْمَفْعُول) typically take?","o":["Nāʾib Fāʿil (Pro-agent)","Fāʿil (Agent)","Mafʿūl bihi (Direct object)","Mubtadaʾ (Subject)"],"e":"The Ism al-Mafʿūl functions like a passive verb, meaning it requires a pro-agent rather than an active agent.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 55"},{"id":"5d3b9ca7-7654-4aef-b47c-28ec077d815e","t":"advanced","p":"How many total grammatical configurations are derived from the relationship between a ṣifah mushabbahah (صفة مشبهة) and its maʿmūl (معمول)?","o":["36","12","24","48"],"e":"The total is reached by multiplying the 2 states of the ṣifah (nakirah or maʿrifah), the 3 cases of the maʿmūl (rafʿ, naṣb, or jarr), and the 6 states of the maʿmūl regarding definiteness and connection.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 56"},{"id":"a45b57b0-acb9-46ba-9c74-cdb70d6dac2a","t":"advanced","p":"Which vowel is preferred on the letter sheen (ش) in the number 'ʿasharah' when counting masculine items?","o":["Fathah","Sukūn","Kasrah","Ḍammah"],"e":"It is preferred to use a fathah on the sheen for masculine items and a sukūn for feminine items.","s":"Mutammimah al-Ājurrūmiyyah · Lesson 60"},{"id":"bc7031b5-43ac-490e-8c69-1fd4926cd988","t":"vocabulary","p":"Linguistically, what are the two core meanings signified by the root letters (خ-ل-ل) of the word Khalīl?","o":["Thinness (diqqa) and a gap or opening (furja)","Straightness and strength","Love and companionship","Heat and intensity"],"e":"Ibn Faris notes in Maqāyīs al-Lughah that this root refers to thinness or a gap, signifying a friend whose love enters the very pores of the heart.","s":"Lāmiyyat Abī Ṭālib · Lesson 1"},{"id":"37639e6c-140d-4842-b565-3bb885f469ae","t":"passage","p":"In the grammatical structure of verse 3, when is the response (jawāb) to the temporal particle lammā finally provided?","o":["In verse 14","In the second half of verse 3","At the beginning of verse 4","It is left implied and never explicitly stated"],"e":"Abu Talib intentionally delays the response until verse 14, where he says 'ṣabartu lahum nafsī,' to highlight the long observation of betrayal before his decision to remain steadfast.","s":"Lāmiyyat Abī Ṭālib · Lesson 2"},{"id":"571c2ebf-1841-461e-99b3-0380c2b99ef2","t":"passage","p":"Which specific group is identified as the 'questionable people' (adhinnatan) in the context of verse five?","o":["The Banū Bakr b. ʿAbd Manāh","The Banū Khuzāʿah","The Banū Umayyah","The Banū Makhzūm"],"e":"Abū Ṭālib refers to the Banū Bakr b. ʿAbd Manāh as the questionable tribe the Quraysh allied with to oppose the Banū Hāshim.","s":"Lāmiyyat Abī Ṭālib · Lesson 3"},{"id":"0ad62da2-b50e-45f6-adf2-2c55deaf2152","t":"passage","p":"Linguistically, what is the specific number range indicated by the term rahṭ (رهط)?","o":["A group of 3 to 10 people","A group of 10 to 20 people","A group of exactly 40 people","A group of more than 100 people"],"e":"The term refers to a small gathering or tribe, specifically numbering between three and ten individuals.","s":"Lāmiyyat Abī Ṭālib · Lesson 4"},{"id":"cadaeb9e-3b7c-4c56-93ce-905b489deff5","t":"passage","p":"What is the linguistic connection between the root ʿ-w-dh (seeking refuge) and the term al-ʿuwwadh (bone marrow)?","o":["The marrow is a substance that is constantly protected deep within the bone, inaccessible to enemies","Both terms refer to something soft and vulnerable that must be discarded","The root refers to the act of breaking a bone to reach the center","The marrow represents the blood that is spilled when protection is lost"],"e":"Linguistically, al-ʿuwwadh refers to bone marrow because it is protected within the hard casing of the bone; seeking refuge (aʿūdhu) implies seeking a similarly impenetrable state of safety.","s":"Lāmiyyat Abī Ṭālib · Lesson 5"},{"id":"8bd76fc9-2ad7-4d20-882d-5550ee370e1d","t":"passage","p":"What is the primary rhetorical significance of the scale tafʿāl (تفعال) in Arabic morphology?","o":["It signifies multiplicity (takthīr) and intensification (mubālaghah)","It indicates a profession or permanent craft","It denotes a temporary or accidental action","It represents the physical size of an object"],"e":"Patterns like tawqāf and tardād indicate that an action is performed frequently or with great intensity.","s":"Lāmiyyat Abī Ṭālib · Lesson 6"},{"id":"ad5d6756-d12b-40e8-ad31-921203d39493","t":"passage","p":"What does the root ḥ-ṭ-m (حَطْم) primarily signify in the context of the tribes' movement?","o":["To break or destroy something by stomping on it","To travel silently at night","To gather in large groups for prayer","To set up temporary shelters"],"e":"The term denotes the sheer force and energy of the movement, implying that the tribes are so vigorous they crush the vegetation beneath them.","s":"Lāmiyyat Abī Ṭālib · Lesson 7"},{"id":"ae0bd8c8-061b-4420-acc5-66c20404adbe","t":"passage","p":"When the idiom 'lā abā laka' (لَا أَبَالَكَ) is used in the context of praise (madḥ), what does it primarily signify?","o":["The person is unique and has no equal or predecessor like him.","The person has reached maturity without parental guidance.","The person has successfully inherited all his father's traits.","The person is of unknown lineage but possesses great wealth."],"e":"In classical Arabic, negating the father in praise suggests the individual is so distinct and incomparable that he stands alone, rather than merely being a likeness of a predecessor.","s":"Lāmiyyat Abī Ṭālib · Lesson 8"},{"id":"7b278680-0676-4b2b-b625-f81580ebe553","t":"passage","p":"What is the significance of the metaphor 'weighing out a ṣāʿ for a ṣāʿ' (نَكِلْ لَهُمَا صَاعًا) at the end of this section?","o":["A promise of exact and equal retribution for the harms committed.","A promise to provide food to those suffering from the boycott.","An intention to pay the blood money for those killed in skirmishes.","A declaration of fair trade between the tribes of Makkah."],"e":"Using the ṣāʿ (a volumetric measure) as a metaphor indicates that the retribution will be precise, matching the severity and nature of the mistreatment received.","s":"Lāmiyyat Abī Ṭālib · Lesson 8"},{"id":"0ca2dc18-7a05-4427-995d-8a661533351d","t":"passage","p":"What is the linguistic implication of the root gh-sh (غش) in the context of providing advice (nuṣḥ)?","o":["Providing hasty, weak, or incomplete counsel","Deliberate and calculated lying","Hiding the truth for the sake of protection","Speaking the truth in a harsh manner"],"e":"Linguistically, the root implies weakness or haste; ghish occurs when someone provides incomplete or insincere advice rather than thorough, honest counsel.","s":"Lāmiyyat Abī Ṭālib · Lesson 9"},{"id":"c089e929-d96f-4e10-b70e-f7d17221aba4","t":"passage","p":"Which two branches of the family of ʿAbd Manāf defected from their brothers to join the boycott against the Prophet ﷺ?","o":["Banū ʿAbd Shams and Banū Nawfal","Banū Hāshim and Banū al-Muṭṭalib","Banū Makhzūm and Banū Asad","Banū Jumaḥ and Banū Sahm"],"e":"While Banū Hāshim and Banū al-Muṭṭalib remained loyal to the Messenger ﷺ, the other two branches of ʿAbd Manāf—ʿAbd Shams and Nawfal—joined the rest of the Quraysh in enforcing the blockade.","s":"Lāmiyyat Abī Ṭālib · Lesson 10"},{"id":"28a95fb7-4536-4e9a-bf69-af5756eea530","t":"passage","p":"What is meant by the phrase ḥawmat al-majd (حومة المجد)?","o":["The absolute center and thickest part of glory and nobility.","The outer edges of a tribe's territory.","The ancient history of the Arab people.","A specific location in Makkah where the leaders met."],"e":"The word ḥawma refers to the thickest part of a battle or the concentrated center of something; ḥawmat al-majd places the Prophet ﷺ at the pinnacle of noble lineage.","s":"Lāmiyyat Abī Ṭālib · Lesson 11"}],[{"id":"6d90ae6b-24bc-4e20-8c8c-b0279cebe301","t":"advanced","p":"In the linguistic analysis of the title, what does the first instance of 'Iʿrāb' mean?","o":["Clarification and making clear (al-ibānah)","The change of word endings","The science of application","The removal of honor"],"e":"Linguistically, iʿrāb (إعراب) means clarification or making something clear, derived from the root 'aʿraba'.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 1"},{"id":"9ae7360b-c1e5-483b-b75e-06958dfc0dfa","t":"advanced","p":"According to the Basran school (al-Baṣriyyūn), the Basmalah is primarily viewed as which type of sentence?","o":["A nominal sentence (jumlah ismiyyah)","A verbal sentence (jumlah fiʿliyyah)","A conditional sentence (jumlah sharṭiyyah)","An interrogative sentence"],"e":"The Basran school traditionally prefers to assume a hidden subject (mubtadaʾ), making the sentence structure nominal.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 1"},{"id":"d6c81f1f-16a9-4814-9312-e362fd52aae0","t":"advanced","p":"Which scholar argued that the hidden verb in the Basmalah should be specific to the action and placed at the end for exclusivity (ḥaṣr)?","o":["Al-Zamakhsharī","Al-Kāfiyajī","Ibn Hishām","Khālid al-Azhari"],"e":"Al-Zamakhsharī proposed assuming a verb like 'aqraʾu' at the end to achieve the benefit of restriction, meaning 'With the name of Allah alone I read'.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 1"},{"id":"3e065234-460d-4f91-9746-eb6dc4570e7d","t":"advanced","p":"What is the linguistic opposite (naqīḍ) of the word al-awwal (الأول)?","o":["Al-Ākhir (الأخير)","Al-Ākhar (الآخر)","Al-Qadīm (القديم)","Al-Munṭaliq (المنطلق)"],"e":"Linguistically, al-awwal (the first) is the opposite of al-ākhir (the last), whereas al-ākhar means 'another'.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 2"},{"id":"a635b144-b792-4da9-81ef-58e905729419","t":"advanced","p":"In the morphological reconstruction of 'lākinnā' (لكنَّا), what were the two original words?","o":["Lākin and Anā","Lākin and Naḥnu","Lā and Kinna","Lākinna and Nā"],"e":"Lākinnā is a contraction of 'lākin' and 'anā' (but I), where the hamzah was dropped and the nūns were merged.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 2"},{"id":"bb3c5ddb-85be-4bb8-a6b9-5881c6461c6e","t":"advanced","p":"Which scholar is noted for requiring that kalām provide a 'new benefit' (fāʾidah jadīdah) to the listener?","o":["Ibn Mālik","Ibn Hishām","Al-Zamakhsharī","Abū Ḥayyān"],"e":"Ibn Mālik is identified as a scholar who conditions kalām upon providing information the listener did not previously know.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 2"},{"id":"b571a480-a7a5-409b-91fb-9ee3352009f6","t":"advanced","p":"Which type of inflection (iʿrāb) occurs when a word or sentence occupies a functional position but cannot display vowels?","o":["Al-iʿrāb al-maḥallī","Al-iʿrāb al-lafẓī","Al-iʿrāb al-taqdīrī","Al-iʿrāb al-uṣūlī"],"e":"Al-iʿrāb al-maḥallī is positional inflection, where the grammatical state is determined by the word's place in the sentence rather than apparent or estimated vowels.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 3"},{"id":"9f28e3a7-761e-4683-b603-87dd13d642c8","t":"advanced","p":"What is the primary criterion for determining if a sentence has a place (maḥal) in grammatical inflection?","o":["If it can be replaced by a mufrad (non-sentence) word that would have iʿrāb","If it begins with a noun","If it contains a relative pronoun","If it follows a verb of action"],"e":"A sentence is said to have a maḥal only if it is in the power of a mufrad, meaning it can be substituted by a non-sentence word that would experience rafʿ, naṣb, or jarr.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 3"},{"id":"56ebb338-de49-4188-a179-fa8dcce26b22","t":"advanced","p":"What grammatical state does the sentence predicate (khabar) of 'kāna' and its sisters occupy?","o":["Naṣb","Rafʿ","Jarr","Jazm"],"e":"The predicates of kāna and the verbs of proximity (kāda) are always in the place of naṣb (accusative).","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 3"},{"id":"b2533729-d43e-431e-bb5a-70968f95fecb","t":"advanced","p":"How is taʿlīq (تعليق) defined in the context of Arabic syntax?","o":["The suspension of verbal governance while maintaining the positional governance.","The total nullification of governance both verbally and positionally.","The requirement for a word to be moved to the end of a sentence.","A process that only occurs with transitive verbs requiring one object."],"e":"Taʿlīq refers to ibṭāl al-ʿamal lafḍan (voiding governance verbally) while keeping it maḥallan (positionally).","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 4"},{"id":"d874eaf4-4560-4506-820b-537ad363fef9","t":"advanced","p":"What is the grammatical position of a sentence that follows a ḍarf (adverb) such as ḥaythu (حيث)?","o":["Fī maḥalli jarrin (Genitive)","Fī maḥalli rafin (Nominative)","Fī maḥalli naṣbin (Accusative)","Fī maḥalli jazmin (Jussive)"],"e":"Sentences following adverbs act as a muḍāf ilayh and are therefore in the position of jarr.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 4"},{"id":"591ef193-b765-4989-b43d-8b728a55d4e1","t":"advanced","p":"Which mnemonic describes the scenarios where fāʾ (فاء) must be attached to the conditional response?","o":["Ismiyyatun, ṭalabiyyatun, wa-bi-jāmidin...","Abjad Hawwaz Ḥuṭṭī","Anaytu (أنيت)","Sāʾaltumūnīhā (سألتمونيها)"],"e":"This poem lists nominal sentences, instructional sentences, static verbs, negation, and future markers as requiring the fāʾ.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 4"},{"id":"f489979f-5e55-404f-a810-53707c408e2b","t":"advanced","p":"Which two criteria must be met for a conditional answer to be considered in a state of jazm?","o":["The tool must be jāzimah and the answer must have fāʾ or idhā al-fujāʾiyyah","The tool must be jāzimah and the verb must be present tense","The tool must be non-jāzimah and the answer must be a nominal sentence","The tool must be a particle and the answer must not have a conjunction"],"e":"A sentence only occupies the position of jazm if the conditional tool has the power to govern and the sentence is linked by fāʾ or idhā al-fujāʾiyyah.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 5"},{"id":"54284d21-9765-4045-8114-058ed9a442fa","t":"advanced","p":"In the phrase 'In qāma akhūka', what is the grammatical state of the verb 'qāma'?","o":["The verb is fī maḥalli jazmin (local inflection)","The entire sentence is in jazm","The verb is in a state of rafʿ","The verb has no grammatical state"],"e":"Because a past-tense verb is mabnī, it receives local inflection (iʿrāb maḥallī) in the position of jazm, but this does not extend to the entire sentence.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 5"},{"id":"736a625a-f155-415e-ad5b-2e5efa738960","t":"advanced","p":"What does the jazm of 'yaqʿudā' in the Kufan example 'In qāma wa yaqʿudā akhawāka' prove?","o":["The jazm is localized to the verb alone","The jazm applies to the whole sentence","The tool 'in' has no governing power","The sentence is a jumla mustaʾnafah"],"e":"Since 'yaqʿudā' is in jazm before the sentence is complete (before the noun 'akhawāka'), it must be conjoined specifically to the maḥall of the verb 'qāma' rather than the whole sentence.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 5"},{"id":"76f51f4c-69d4-423a-8d0d-c69089df9322","t":"advanced","p":"What does it mean for a sentence to have no grammatical position (maḥal) from iʿrāb?","o":["It cannot be substituted by a single non-sentence word (mufrad).","It cannot be translated into another language accurately.","It does not contain a subject (mubtadaʾ) or a predicate (khabar).","It is always found at the very end of a discourse or book."],"e":"A sentence has no maḥal when it does not occupy a slot that a single word, such as a khabar or ṣifah, could typically fill.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 6"},{"id":"8ce639cc-5ca7-4043-a68b-a9e74611a184","t":"advanced","p":"What are the two sub-types of the resumed sentence (al-mustaʾnafah)?","o":["Opening of discourse and structurally disconnected.","Verbal and nominal resumptions.","Conditional and explanatory resumptions.","Independent and dependent resumptions."],"e":"The mustaʾnafah is divided into sentences that initiate a speech (al-muftataḥ bihā al-nuṭq) and those that occur during speech but are structurally independent (al-munqaṭiʿah).","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 6"},{"id":"d4e03047-d495-426d-ac5e-ebf4979bfbaf","t":"quran-irab","p":"In Sūrah Yūnus (10:65), why is 'inna al-ʿizzata lillāhi jamīʿan' analyzed as mustaʾnafah rather than maḥkiy bi-al-qawl?","o":["To avoid the implication that the disbelievers were the ones affirming Allah's honor.","Because the word 'inna' can never follow the verb 'qāla'.","Because it is a circumstantial clause (ḥāl) for the Prophet ﷺ.","Because the verse ends at 'qawluhum' according to all readings."],"e":"If it were the quoted speech (maḥkiy bi-al-qawl), it would wrongly imply the disbelievers made that statement, which would not cause the Prophet ﷺ grief.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 6"},{"id":"a12927f1-a380-4865-bc5b-537630bf1503","t":"advanced","p":"Why does the ṣīlat al-mawṣūl lack a place in iʿrāb?","o":["Because a single word (mufrad) cannot replace it in its specific role","Because it is always followed by a verb","Because it is considered a fragmented sentence","Because it only occurs after particle relatives"],"e":"A sentence only occupies a grammatical place if a single word can stand in its position; however, the role of a ṣīla is inherently tied to a full sentence structure.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 7"},{"id":"e48e1570-274a-4ec5-91c0-8a117988ab41","t":"advanced","p":"Which particle is used to create a maṣdar muʾawwal and follows verbs like wadda (to wish)?","o":["Law","An","Mā","Kay"],"e":"The particle law is used as a mawṣūl ḥarfī specifically after verbs expressing a wish to convert the following sentence into an interpreted infinitive.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 7"},{"id":"4159090d-b317-4ba1-b43c-62b681f27fe5","t":"advanced","p":"How is a jāmid (non-derived) noun like 'asad' (lion) interpreted within a maṣdar muʾawwal structure?","o":["By using the maṣdar of kaun (being) or deriving a conceptual noun like asadiyya","By changing it into a past-tense verb","By ignoring the particle relative","By deleting the predicate of the sentence"],"e":"Since a jāmid noun has no direct verbal noun, a facilitator like 'kaun' or a conceptual derivation is used to fulfill the grammatical requirement of the maṣdar muʾawwal.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 7"},{"id":"940bcd9b-50ce-4296-b025-e9350d02a498","t":"advanced","p":"What is the primary technical definition of the explanatory sentence (al-jumlat al-tafsīriyyah)?","o":["A sentence that reveals the reality of the element preceding it","A sentence that substitutes for a single noun (mufrad)","A sentence that occupies the position of a predicate (khabar)","A sentence that follows a conditional particle"],"e":"The explanatory sentence is defined as al-kāshifatu li-ḥaqīqati mā talīhi, or that which reveals the reality of what it follows.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 8"},{"id":"021c9c66-3c70-4e59-bbad-23b5131c766e","t":"advanced","p":"Why do sentences clarifying the 'pronoun of the matter' (dhamīr al-shaʾn) possess a grammatical place (maḥall)?","o":["Because they function as a predicate (khabar), which is an essential pillar","Because they are always preceded by a preposition","Because they explain a definite noun","Because they are introduced by the particle 'an'"],"e":"In the structure of dhamīr al-shaʾn, the clarifying sentence functions as the khabar, and since the khabar is an ʿumdah, the sentence occupies a place of rafʿ.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 8"},{"id":"e716f783-b6b0-41f5-9ede-8f29eb97f012","t":"advanced","p":"Which particle is considered a dedicated explanatory particle (ḥarf al-tafsīr)?","o":["Ay (أَيْ)","In (إِنْ)","Law (لَوْ)","Qad (قَدْ)"],"e":"The particle ay (أَيْ) is a specific particle used to introduce an explanation for a preceding word or phrase.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 8"},{"id":"1da56bce-365e-4fa9-a631-00fb9021aa10","t":"advanced","p":"Why does the particle idhā (إذا) generally not cause jazm (apocopation) in its answer?","o":["Because it indicates certainty, unlike the doubt implied by 'in'","Because it is a noun and nouns cannot govern verbs","Because it only enters upon nominal sentences","Because it is too weak to reach the second sentence"],"e":"Idhā implies certainty (when), whereas the apocopating particle 'in' implies doubt (if); this semantic difference prevents idhā from governing jazm.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 9"},{"id":"8f918ee8-afef-4025-9823-d8e774fdd5f4","t":"advanced","p":"When an oath (qasam) and a condition (sharṭ) appear together with a single answer, which one does the answer belong to according to the general rule?","o":["Whichever of the two appears first","The condition, regardless of order","The oath, regardless of order","Whichever of the two appears last"],"e":"The rule states that when an oath and a condition gather, the answer belongs to the preceding one, and the answer to the second is omitted because the first indicates it.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 9"},{"id":"e1b17eda-4713-41d2-a30c-2f733334728b","t":"advanced","p":"What is a formal obstacle (māniʿ lafẓī) that prevents a sentence from being a ṣifah of a preceding noun?","o":["The presence of a wāw conjunction","The sentence being informative (khabariyyah)","The noun being a proper name","The sentence being in the past tense"],"e":"An adjective cannot be separated from its noun by a conjunction like the wāw; if a wāw exists, the sentence is likely a ḥāl.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 9"},{"id":"f55003e7-08d5-420f-9784-a4f35936a43b","t":"advanced","p":"Why must a preposition (jārr) generally have an attachment (taʿalluq)?","o":["Because prepositions act as bridges to link the meaning of an action to a noun","To define the tense of the following noun","To ensure the noun remains in the state of rafʿ","Because a preposition is technically a type of verb"],"e":"Prepositions do not convey independent meanings and must connect to a verb or its equivalent to transfer the action's meaning to the noun.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 10"},{"id":"3124a98b-663d-4a8c-a7ad-c6dc77032f4e","t":"advanced","p":"Which term is preferred by grammarians when referring to an 'extra' preposition in the Qur'ān?","o":["Ḥarf al-Ṣilah","Ḥarf al-Ziyādah","Ḥarf al-Laghw","Ḥarf al-Iḍāfah"],"e":"Scholars prefer the term ḥarf al-ṣilah to avoid the implication that any word in the Qur'ān is redundant or unnecessary.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 10"},{"id":"b0626b4f-0000-4912-94e2-deb8aa23d6e7","t":"advanced","p":"In the phrase 'kafā billāhi shahīdā', how is the word 'Allāh' grammatically analyzed according to Al-Naḥw al-Wāfī?","o":["Marfūʿ with a ḍammah muqaddarah due to the vowel required by the extra bā'","Majrūr lafẓan and manṣūb maḥallan","Manṣūb as a ḥāl","Majrūr as a muḍāf ilayh"],"e":"For declinable nouns, it is more accurate to say the state is marfūʿ with a hidden ḍammah prevented by the kasrah of the extra preposition.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 10"},{"id":"3887580d-5586-4c9b-8725-90b9f6e18777","t":"quran-irab","p":"In the verse 'Afī Allāhi shakkun' (أفي الله شك), why is it preferred to analyze 'shakkun' as a fāʿil rather than a mubtadaʾ?","o":["To avoid separating the word 'Allāh' from its following adjective 'fāṭiri'","To allow the sentence to be interrogative","Because it is the only way to explain the rafʿ case","Because the jārr majūr is too weak to be a khabar"],"e":"Treating 'shakkun' as a fāʿil makes it part of the governor, preventing it from being an ajnabī separator between the name of Allah and its attribute.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 11"},{"id":"30b6caf5-487e-47f3-9676-4958ad9a984f","t":"advanced","p":"In which position is it mandatory for the jārr majūr to connect to a hidden verb like istaqarra (استقر) rather than a participle?","o":["Ṣilah (Relative clause)","Ṣifah (Adjective)","Ḥāl (Circumstantial qualifier)","Khabar (Predicate)"],"e":"A ṣilah must be a complete sentence (jumlah), and the verbal structure provides a complete sentence in a way that a participle does not.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 11"},{"id":"2ef91f31-e7ce-4a40-8ecf-8ea0970e7001","t":"advanced","p":"What is the term for a word that improperly separates a mawṣūf (noun described) from its ṣifah (adjective)?","o":["Ajnabī","Mutaʿalliq","Mustaqarr","Laghw"],"e":"An ajnabī is a 'foreign' word that is not grammatically integrated enough to stand between a noun and its adjective.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 11"},{"id":"7fabf163-3a54-42dd-acef-0c744b42a163","t":"advanced","p":"Which dialect or pronunciation of qaṭ (قط) is used in the Ḥadīth describing Hellfire to mean 'enough'?","o":["Qaṭ (with a sukūn on the ṭā’)","Quṭṭu","Qaṭū","Qaṭṭi"],"e":"While the first four dialects are adverbs of time, the fifth dialect (qaṭ with a sukūn) carries the meaning of 'enough' (yakfīnī).","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 12"},{"id":"25896ec1-aaee-4975-af8a-d52d3a2038e9","t":"advanced","p":"What is a primary difference between ʿawdu (عوض) and abadan (أبدا)?","o":["Abadan can be used in affirmative sentences, while ʿawdu is restricted to negative contexts","ʿAwdu is always muʿrab, while abadan is mabnī","Abadan is only used for the past, while ʿawdu is for the future","There is no grammatical difference between the two"],"e":"Abadan can be used in both affirmative and negative sentences (e.g., in the Qur'an regarding Paradise), whereas ʿawdu is restricted to negative contexts.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 12"},{"id":"a7044eea-cd03-4dc4-8cc2-ac73189a045b","t":"advanced","p":"In the context of responding to a command, which function does the particle naʿam (نعم) perform?","o":["Promise (Waʿd)","Confirmation (Taṣdīq)","Acknowledgment (Iʿlām)","Suddenness (Mufājaʾah)"],"e":"When naʿam follows a command or request (ṭalab), it functions as a promise to carry out the action.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 12"},{"id":"88710527-7b50-4d87-9b7c-b0833da63f65","t":"advanced","p":"What is the primary grammatical function of the word idh (إِذْ)?","o":["An adverb (ẓarf) for the past tense","A particle of negation for the future tense","A preposition indicating a physical location","An introductory particle for nominal sentences only"],"e":"Idh is primarily used as a ẓarf for the past tense and can enter upon both nominal and verbal sentences.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 13"},{"id":"c7c2c974-9986-4a7c-a4f9-1570be003ed0","t":"advanced","p":"What happens to a present tense verb (muḍāriʿ) when it is preceded by lammā (لَمَّا) acting as a particle of negation?","o":["It becomes apocopated (majzūm)","It becomes nominative (marfūʿ)","It becomes subjunctive (manṣūb)","The verb tense remains in the future"],"e":"When lammā acts as a particle of negation (ḥarf jazm), it places the present tense verb in a state of jazm and flips its meaning to the past.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 13"},{"id":"b7e85999-ffac-4e86-b853-86439cea2007","t":"advanced","p":"According to grammarians, which of the following is NOT a function of the response particle naʿam (نَعَمْ)?","o":["Qasam (Acting as an oath)","Tasdīq (Affirmation of a statement)","Iʿlām (Informing or confirming a question)","Waʿd (Promising a command)"],"e":"Naʿam functions for affirmation, informing, or promising, but it is not a qasam (oath) itself.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 13"},{"id":"fe04bb90-9afc-422a-8ee2-05d6219cd5df","t":"advanced","p":"If the particles mā and in appear together as 'mā in' (مَا إِنْ), what is the function of in?","o":["Extra/Emphatic (zāʾidah)","Conditional (sharṭiyyah)","Negatory (nāfiyah)","Infinitive (maṣdariyyah)"],"e":"When mā precedes in, mā is the primary negatory particle and in is added as an extra emphatic element.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 14"},{"id":"d631cfd2-f3e1-422a-a6e5-178e8cd5dd58","t":"advanced","p":"Which facet of lawlā (لَوْلَا) indicates that a result was prevented because of the presence of a condition?","o":["Imtināʿ li-wujūd","Taḥḍīḍ","Tawbīkh","ʿArḍ"],"e":"Imtināʿ li-wujūd refers to the non-occurrence of the main clause due to the existence of the condition stated after lawlā.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 14"},{"id":"a8629e40-0345-48f4-a14d-78938a189903","t":"advanced","p":"What is the difference between taḥḍīḍ (تَحْضِيض) and ʿarḍ (عَرْض)?","o":["Taḥḍīḍ is forceful urging, while ʿarḍ is gentle urging","Taḥḍīḍ is for the past, ʿarḍ is for the future","Taḥḍīḍ negates, while ʿarḍ affirms","There is no difference; they are synonyms"],"e":"Taḥḍīḍ involves intense encouragement (bi-izʿāj), whereas ʿarḍ involves polite or gentle encouragement (bi-rifq).","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 14"},{"id":"47b64f5e-3805-4590-aad4-c4257a3f6d9d","t":"advanced","p":"What is the primary reason Ibn Ṭāhir argued that an (أَنْ) cannot enter upon a past tense verb (māḍī)?","o":["The particle an inherently restricts the verb to the future tense","The māḍī verb is structurally incompatible with particles","The māḍī verb must only be preceded by the particle qad","An al-maṣḍariyyah is exclusively for the subjunctive case"],"e":"Ibn Ṭāhir believed that because the particle 'an' restricts a verb's meaning to the future (istiqbāl), it cannot be joined with a verb that is inherently fixed in the past.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 15"},{"id":"4f595833-029c-4524-8893-13446270ea9d","t":"advanced","p":"Which of the following is a necessary condition for an (أَنْ) to be considered al-mufassirah (explanatory)?","o":["It must be preceded by a complete sentence","It must be preceded by a preposition","It must follow the literal letters of the root qā-wa-la","It must govern the following verb in the subjunctive case"],"e":"For 'an' to be explanatory, it must be preceded by a full sentence that contains the meaning of speech without using the literal letters of 'qawl'.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 15"},{"id":"9c41503c-89e3-4632-ac38-f4bc577f8e7a","t":"quran-irab","p":"In the verse regarding the end of the believers' call (Qurʾān 10:10), why is the particle an (أَنْ) not explanatory (mufassirah)?","o":["The preceding phrase is not a complete sentence","It follows a preposition","It is followed by a nominal sentence","The preceding verb contains the letters of qawl"],"e":"The phrase 'ākhiru daʿwāhum' is not a complete sentence; therefore, the 'an' that follows is the lightened version of 'anna' (mukhaffafah), not the explanatory particle.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 15"},{"id":"7ad4b0d6-350f-43ce-a101-d613f0bfdbfc","t":"quran-irab","p":"What is the primary function of ayy (أَيّ) in the verse: \"ayyamā al-ajalayni qadaytu\" (أَيَّمَا الْأَجَلَيْنِ قَضَيْتُ)?","o":["Conditional (sharṭiyyah)","Interrogative (istifhāmiyyah)","Relative pronoun (mawṣūlah)","Indicator of perfection (kamāl)"],"e":"In this context, it acts as a conditional particle necessitating a condition (fulfilling the term) and a response (no injustice).","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 16"},{"id":"38dea8af-9299-492f-be71-7a1944344d84","t":"advanced","p":"In the construction \"yā ayyuhā al-nās\" (يَا أَيُّهَا النَّاسُ), why is ayy (أَيّ) inserted?","o":["To separate the vocative particle yā from a noun with alif-lām","To provide a subject for the vocative","To emphasize the call to the people","To change the noun into a conditional state"],"e":"It acts as a buffer because Arabic avoids having two markers of definiteness (yā and al-) occur consecutively.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 16"},{"id":"9f1e409c-6a9e-4f04-bd16-da6da4f2cc7c","t":"advanced","p":"In the phrase \"law lam yakhaf Allāha lam yaʿṣih\" (لَوْ لَمْ يَخَفِ اللَّهَ لَمْ يَعْصِهِ), why is the result \"not disobeying\" not negated?","o":["Because awe and reverence serve as an independent cause for obedience","Because the person actually did disobey","Because fear is the only reason people obey","Because the word law here is used for wonder rather than a condition"],"e":"The sentence praises the person whose reverence is such that they would not disobey even if the cause of fear were theoretically removed.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 16"},{"id":"fcd65dcd-a36d-4cc8-883a-eb7d7261cd1c","t":"advanced","p":"What is the function of the wāw al-istināf (واو الاستئناف)?","o":["To mark the start of a syntactically independent sentence","To connect two words in the same case","To introduce a circumstantial state","To indicate accompaniment"],"e":"Wāw al-istināf is the wāw of resumption, used to begin a new sentence that is not grammatically tied to the previous one.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 17"},{"id":"0648163d-2e96-41b1-9d93-ab180c1b44be","t":"advanced","p":"What is the meaning of the word qad (قَدْ) when it is used as a substantive noun (ism)?","o":["Sufficient (ḥasb)","It suffices (yakfī)","Perhaps (laʿalla)","Verily (inna)"],"e":"When qad functions as a substantive noun, it is synonymous with ḥasb, which means 'sufficient' or 'enough.'","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 17"},{"id":"2b5ddebf-3652-4ddc-bb96-93e21419a628","t":"quran-irab","p":"In the verse regarding the Battle of Uḥud, why is the wāw before 'ṭā’ifatun' (طائفةٌ) considered istināf or ḥāl rather than ʿaṭf (conjunction)?","o":["Because the second group did not receive the same blessing as the first","Because both groups are the same","Because it is in the naṣb case","Because there is no verb following it"],"e":"Grammatically, the nominative case (rafʿ) and context show this group (hypocrites) had a different state from the believers who received tranquility.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 17"},{"id":"788e7097-a906-4e0b-8dc6-35cf00d5673f","t":"advanced","p":"What is the specific requirement for the wāw al-maʿiyyah to induce naṣb on an imperfect verb?","o":["It must be preceded by a negation (nafī) or a request (ṭalab)","It must be preceded by a nominal sentence","It must be preceded by a particle of emphasis","It must be the first word in the sentence"],"e":"The wāw of accompaniment or gathering requires a preceding negation or request—such as a command, prohibition, or wish—to function in the subjunctive mood.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 18"},{"id":"2ee0b819-419e-4821-9cfb-845ab87a5702","t":"quran-irab","p":"In the verse regarding the People of the Cave, where does the theory of wāw al-thamāniyah suggest the wāw appears?","o":["Before the mention of the eighth person","Before the mention of the fourth person","Before the mention of the sixth person","Before the mention of the tenth person"],"e":"The theory posits that in the phrase 'wa yaqūlūna sabʿah wa thāminuhum kalbuhum,' the wāw is specifically linked to the number eight.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 18"},{"id":"8ab9215a-455c-4d2b-b23b-4cc35f6a40c8","t":"advanced","p":"Which type of wāw is found in the line of poetry by Imruʾ al-Qays: 'wa laylin ka mawji al-baḥri'?","o":["Wāw Rubba","Wāw al-Qasam","Wāw al-Maʿiyyah","Wāw al-Zāʾidah"],"e":"In this context, the wāw carries the meaning of 'rubba' (many a), which functions as a preposition causing jarr on the word 'laylin'.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 18"},{"id":"e488107d-9103-4989-b57b-5888cf93f505","t":"advanced","p":"Which category of mā (ما) allows a preposition like rubba (رب) to enter upon a verbal sentence?","o":["Mā al-Kāffah (ما الكافة)","Mā al-Nāfiyah (ما النافية)","Mā al-Maṣdariyyah (ما المصدرية)","Mā al-Zāʾidah (ما الزائدة)"],"e":"Mā al-kāffah stops the governance of the preposition and acts as an enabler (muhayyiʾah), allowing it to enter structures it normally cannot.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 19"},{"id":"a2d3a79f-a28d-4f97-8d8a-6d018d126e23","t":"advanced","p":"According to the text, what is the underlying meaning that the particle ammā (أما) stands in place of?","o":["Mahmā yakun min shayʾ (مهما يكن من شيء)","Inna wa akhwātuhā (إن وأخواتها)","Laysa (ليس)","Idhā al-fujāʾiyyah (إذا الفجائية)"],"e":"Ammā functions as a conditional particle and replaces the phrase 'whatever the case may be' (mahmā yakun min shayʾ).","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 19"},{"id":"4a0a1369-c9fa-47f1-8ff2-d3165e700afb","t":"advanced","p":"What is the consequence of adding mā al-kāffah to the verb qalla (قل)?","o":["It strips the verb of its requirement for a fāʿil (subject).","It makes the verb transitive.","It changes the verb to the present tense.","It turns the verb into a maṣdar."],"e":"When mā attaches to qalla, ṭāla, or kathura, the verb is barred (makkūf) from taking a subject and functions similarly to a negation particle.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 19"},{"id":"979de257-8608-4b78-b71d-3ddc35db9dd9","t":"advanced","p":"What is the primary difference between kalām and jumlah in Arabic grammar?","o":["Kalām must provide a complete benefit whereas jumlah only requires a predicate relationship","Kalām is a broader category than jumlah","Jumlah requires a complete benefit whereas kalām only needs a predicate relationship","There is no grammatical difference between the two terms"],"e":"Kalām refers to speech that provides a complete benefit (fāʾidah), while jumlah is a wider category that only requires an attribution (isnād) between words.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 20"},{"id":"ed5287a2-850e-4ffb-bc78-cc5e2003423b","t":"advanced","p":"Which of the following particles is an exception to the rule of taʿalluq (connection)?","o":["Rubba","Min","ʿAlā","Fī"],"e":"Particles like Rubba, Lawlā, and specific usages of the Kāf are among the exceptions that do not require a grammatical connection.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 20"},{"id":"e3180fda-57c9-4475-a340-9b79a7bf831c","t":"advanced","p":"What does the particle qad typically signify when used with a past tense verb?","o":["Certainty/Realization (taḥqīq)","Expectation (tawaqquʿ)","Rarity (taqlīl)","Futurity (istiqbāl)"],"e":"When paired with the past tense, qad denotes realization or certainty that the action has already occurred.","s":"al-Iʿrāb ʿan Qawāʿid al-Iʿrāb · Lesson 20"}]]
